(window.MUSEUM_PAINT_T = window.MUSEUM_PAINT_T || {})["ko"] = {"ui":{"lead":"사람들은 게임을 즐기기만 한 것이 아니라 그림으로도 남겼습니다. 3300년에 걸친 그림과 조각을 확대해서 구석구석 살펴보세요.","details":"볼거리","links":"이 게임 보기·하기","record":"작품 정보","game":"게임","exhibit":"소장품","room":"전시실","room_chance":"우연의 도구","hint":"핀치·휠로 확대 · 드래그로 이동 · 번호를 탭","r_artist":"작가","r_date":"연대","r_place":"지역","r_medium":"재질·기법","r_size":"크기","r_museum":"소장","r_credit":"입수","r_rights":"이미지","met":"메트로폴리탄 미술관","cc0":"오픈 액세스(퍼블릭 도메인)","metlink":"미술관의 작품 페이지","credit":"이미지는 메트로폴리탄 미술관·클리블랜드 미술관·시카고 미술관·암스테르담 국립미술관의 오픈 액세스(퍼블릭 도메인)입니다.","cma":"클리블랜드 미술관","aic":"시카고 미술관","rijks":"암스테르담 국립미술관"},"nefertari":{"title":"세네트를 두는 네페르타리 왕비","artist":"니나 드 가리스 데이비스(모사)","date":"원화 기원전 1290~1224년경 · 모사 1921~22년","place":"이집트(왕비의 계곡)","game":"세네트","medium":"종이에 템페라(원래 크기의 1/2 모사)","p":["네페르타리는 람세스 2세의 첫째 왕비입니다. 왕비의 계곡에 있는 그녀의 무덤 벽화를 1921~22년에 무덤 안에서 옮겨 그린 것으로, 원화의 금과 떨어져 나간 부분까지 그대로 옮겼습니다.","왕비는 판 앞에 앉아 보이지 않는 상대와 세네트를 두고 있습니다. 무덤에 그려진 세네트는 단순한 놀이가 아니라 저승으로 가는 여정을 이겨 낸다는 뜻이 있었다고 여겨집니다."],"spots":[["두 종류의 말","판 위에 끝이 뾰족한 말과 실패 모양의 말이 놓여 있습니다. 대국하는 두 사람의 말입니다."],["왕비의 손","말을 집으려는 손끝."],["판과 받침대","판을 옆에서 그렸기 때문에 칸은 보이지 않습니다. 가는 다리의 받침대 위에 놓여 있습니다."],["이름 테두리","타원형 테두리(카르투슈) 안에 왕비의 이름이 적혀 있습니다."],["보이지 않는 상대","맞은편에는 아무도 없습니다. 왕비는 보이지 않는 상대와 대국하고 있습니다."]]},"hydria":{"title":"놀이를 즐기는 아킬레우스와 아이아스(물항아리)","artist":"레아그로스 그룹(으로 추정)","date":"기원전 510년경","place":"그리스(아티카)","game":"주사위 놀이","medium":"테라코타(흑색상)","p":["트로이 전쟁의 진중에서 그리스의 두 영웅 아킬레우스와 아이아스가 판을 사이에 두고 시간을 보내는 장면입니다. 기원전 540년경 도공이자 화가인 엑세키아스가 처음 그린 구도로, 원작은 바티칸 미술관의 암포라에 남아 있습니다.","이 주제는 기원전 540~480년경 크게 사랑받아 150점이 넘는 예가 알려져 있습니다. 이 항아리에서는 가운데에 여신 아테나가 서 있습니다. 두 사람이 하는 것은 주사위를 굴려 말을 움직이는 놀이입니다."],"spots":[["여신 아테나","여신 아테나가 두 사람 사이에 서 있습니다."],["왼쪽의 영웅","창을 든 채로 몸을 숙여 판을 들여다봅니다."],["오른쪽의 영웅","그 역시 무기를 내려놓지 않았습니다. 전쟁 중의 짧은 놀이입니다."],["판","두 사람 사이의 낮은 받침이 판입니다."],["어깨의 그림","항아리 어깨에는 출발하는 전차가 그려져 있습니다."]]},"liubo":{"title":"육박을 두는 두 사람(부장용 인형)","date":"기원전 1세기~기원 1세기","place":"중국(한)","game":"육박","medium":"채색 토기","p":["한나라에서 크게 유행한 육박을 두는 두 사람의 상입니다. 무덤에 넣어, 죽은 뒤에도 즐거움이 이어지기를 바랐습니다.","사진에서는 두 사람 사이에 이 박물관의 소장품이기도 한 육박 판과 뼈 말이 놓여 있습니다. 열띤 한 판의 극적인 순간을 포착한 상입니다."],"spots":[["육박 판","이 박물관의 소장품 「육박 판과 말」과 같은 판입니다. T·L·V 표시가 보입니다."],["왼쪽의 기사","차분하게 판을 바라보고 있습니다."],["오른쪽의 기사","한 손을 들고 입을 크게 벌렸습니다. 좋은 수가 나왔을까요?"],["판 위의 말","뼈 말이 판 양 끝에 놓여 있습니다."],["판 밖의 말","바닥에도 말이 놓여 있습니다."]]},"shahnama":{"title":"부주르지미흐르, 인도의 놀이 「체스」를 풀다(『샤 타흐마스프의 왕서』에서)","artist":"압드 알와하브(로 추정)","date":"1530~35년경","place":"이란(타브리즈)","game":"체스","medium":"종이에 불투명 수채·잉크·은·금","p":["피르다우시의 서사시 『왕서(샤나메)』의 한 장면입니다. 인도 왕이 사신에게 체스판과 말을 들려 보내, 페르시아 왕 누시르반에게 「놀이 방법을 풀어 보라. 풀면 공물을 바치겠다」고 도전합니다.","기한 안에 풀어낸 것은 젊은 현자 부주르지미흐르뿐이었습니다. 『왕서』에서는 페르시아가 답례로 백개먼을 보냈고, 인도는 풀지 못했다고 전합니다. 왕과 신하들이 판과 기사들을 뚫어지게 바라봅니다."],"spots":[["체스판","격자 판 위에 말이 놓여 있습니다. 너무 작아 모양을 알아보기 어려울 정도입니다."],["누시르반 왕","옥좌에 앉아 수수께끼가 풀리기를 지켜봅니다."],["판을 둘러싼 사람들","몸을 내밀고 판을 들여다보는 기사들."],["시구","위아래 틀에는 피르다우시의 시가 적혀 있습니다."],["신하들","붉은 막대가 솟은 터번을 쓴 사람들이 서서 구경합니다."]]},"chaupar":{"title":"차우파르를 두는 시바와 파르바티(『라사만자리』 연작의 한 장)","artist":"누르푸르의 데비다사","date":"1694~95년","place":"인도(바소리, 잠무)","game":"차우파르(루도 조상의 친척)","medium":"종이에 불투명 수채·잉크·은·금","p":["15세기 산스크리트 연애시 『라사만자리』를 그린 연작의 한 장입니다. 시바 신과 아내 파르바티가 호랑이 가죽 위에서 십자 모양의 판을 둘러싸고 있습니다.","시바에게 속아 목걸이를 빼앗긴 파르바티가 돌려 달라고 호소하는 장면입니다. 대담한 색, 모호한 공간의 깊이, 색과 몸짓에 의미를 담는 것이 바소리 화파의 특징입니다."],"spots":[["십자 모양의 판","차우파르와 파치시의 판은 이런 십자 모양입니다."],["판 위의 흰 막대","차우파르에서 던지는 긴 주사위(파사)로 보입니다."],["시바","흰 몸에 목에는 뱀."],["파르바티","손을 내밀며 목걸이를 돌려 달라고 합니다."],["호랑이 가죽","두 사람은 호랑이 가죽 위에 앉아 있습니다."]]},"shogi":{"title":"쇼기를 두는 젊은 남녀(「주나곤 가네스케」, 삼십육가선 미타테)","artist":"스즈키 하루노부","date":"1767~69년경","place":"일본(에도)","game":"쇼기","medium":"목판화(니시키에)","p":["삼십육가선에 빗댄 연작의 한 장으로, 이 그림은 주나곤 가네스케에 빗대었습니다. 여름밤 모기장 곁에서 젊은 남녀가 쇼기판을 둘러싸고 있습니다.","하루노부는 여러 색을 겹쳐 찍는 니시키에를 널리 퍼뜨린 화가입니다. 판 위의 말 배치까지 세밀하게 그렸습니다."],"spots":[["다리 달린 쇼기판","지금과 같은, 다리가 달린 두꺼운 판입니다."],["작은 상자","말을 넣어 두는 상자로 보입니다."],["모기장","초록 모기장이 쳐져 있습니다. 여름밤의 장면입니다."],["안돈(등불)","판을 비추는 등불."],["노래 패","구름 모양 틀에 가선의 이름과 노래가 적혀 있습니다."]]},"sugoroku":{"title":"스고로쿠를 두는 두 아가씨","artist":"초대 우타가와 도요쿠니","date":"에도 시대(18세기 말~19세기 초)","place":"일본(에도)","game":"반스고로쿠(백개먼의 친척)","medium":"목판화(두 장 연결)","p":["판화 두 장을 이은 큰 화면에서, 방에 모인 아가씨들이 반스고로쿠를 즐기고 있습니다. 반스고로쿠는 이 박물관 소장품인 쇼소인의 스고로쿠 판과 같은 계통의, 백개먼의 친척입니다.","판에는 흰 돌과 검은 돌이 놓이고, 오른쪽 아가씨는 통(주사위를 흔드는 그릇)을 들고 있습니다. 창밖으로 후지산이 보입니다."],"spots":[["스고로쿠 판","길쭉한 칸에 흰 돌과 검은 돌이 놓여 있습니다."],["주사위 통","통에 주사위를 넣고 흔듭니다."],["판 밖의 돌","이미 빠져나간 돌일까요, 아직 판에 나오지 않은 돌일까요?"],["후지산","창 너머의 후지산."],["두 장의 이음매","여기서 두 장의 판화가 이어집니다."]]},"eakins":{"title":"체스 두는 사람들","artist":"토머스 에이킨스","date":"1876년","place":"미국(필라델피아)","game":"체스","medium":"나무판에 유화","p":["필라델피아의 한 집 응접실에서 두 친구가 체스를 두고, 화가의 아버지 벤저민 에이킨스가 지켜봅니다. 화가는 꼼꼼한 공간 구성과 정밀한 세부 묘사를 파리의 스승 제롬에게서 배웠습니다.","1881년, 이 그림은 메트로폴리탄 미술관이 생존 화가에게서 기증받은 첫 작품이 되었습니다."],"spots":[["체스 말","어두운 방 안에서 판 위의 말이 밝게 떠오릅니다."],["화가의 아버지","서서 승부를 지켜보는 사람은 화가의 아버지 벤저민입니다."],["오른쪽의 기사","화가 조지 W. 홈스. 화가 아버지의 친구입니다."],["책상 서랍","「벤저민 에이킨스의 아들이 76년에 그렸다」는 뜻의 라틴어가 적혀 있습니다."],["벽난로 위의 그림","스승 제롬의 그림 복제품이 걸려 있습니다."],["고양이","바닥 위에서 고양이만은 승부에 관심이 없어 보입니다."]]},"weiqi":{"title":"바둑 두는 신선 무늬 접시","artist":"작자 미상","date":"1425~36년(명 선덕 연간)","place":"중국","game":"바둑","medium":"조칠(붉은 옻과 초록 옻을 겹쳐 바르고 새김)","size":"높이 3.5·너비 14.9·길이 23.5cm","credit":"플로렌스·허버트 어빙 기증, 2015년","p":["옻칠을 수십 겹 바른 뒤 새겨 내는 '조칠' 접시입니다. 붉은 옻 아래에 초록 옻 층이 있어, 새김의 깊이로 색을 나누어 냅니다. 꽃 모양 테두리 안쪽에 소나무 아래에서 바둑을 두는 신선들이 새겨져 있습니다.","중국에는 나무꾼 왕질이 산에서 신선들의 바둑을 구경하다 정신을 차려 보니 도낏자루가 썩을 만큼 시간이 흘렀다는 '난가' 전설이 있어, 바둑 두는 신선은 사랑받는 소재였습니다. 오른쪽에 선 인물이 누구인지는 기록에 없습니다."],"spots":[["바둑판","두 신선 사이의 바둑판. 줄까지 세밀하게 새겨져 있습니다."],["바둑 두는 신선","바위 곁에 앉아 판을 둘러싼 두 사람."],["서서 보는 사람","조금 떨어져 선 인물. 난가 전설의 나무꾼을 떠올리게 하지만 누구인지는 알 수 없습니다."],["달","하늘에 뜬 둥근 달(해일지도 모릅니다)."],["소나무","가지를 크게 펼친 소나무. 장수와 선경을 나타내는 일이 많은 나무입니다."],["모란 테두리","테두리에는 커다란 모란꽃과 잎이 새겨져 있습니다."]]},"webb":{"title":"백개먼을 하는 두 사람(장식장)","artist":"필립 웹(설계), 에드워드 번존스(그림), 모리스·마셜·포크너 상회(제작)","date":"1861년","place":"영국(런던)","game":"백개먼","medium":"채색한 소나무, 가죽에 유채, 놋쇠, 구리","size":"높이 185.4·너비 114.3·깊이 53.3cm","credit":"로저스 기금, 1926년","p":["윌리엄 모리스가 동료들과 1861년에 세운 회사의 가장 이른 시기 가구입니다. 문짝 가죽 위에 중세풍 옷을 입은 남녀가 백개먼 판을 마주한 모습이 유화로 그려져 있습니다. 이듬해 1862년 런던 국제박람회에도 출품되었습니다.","'미술'과 '공예'의 경계를 없애려 한 아츠 앤드 크래프츠 운동의 생각을 잘 보여 주는 작품입니다. 가죽 배경에 잔점을 두드려 낸 것은 중세 기법을 본뜬 것입니다."],"spots":[["판","두 사람 사이 탁자 위의 백개먼 판."],["남자","말을 손에 들고 판을 바라보는 젊은 남자."],["여자","맞은편에 앉은 여자. 손에 말(또는 주사위 통)을 들고 있습니다."],["발치의 꽃","두 사람의 발치에 꽃이 피어 있습니다."],["두드린 가죽","배경 가죽에 잔점이 두드려져 빛을 받아 반짝입니다."],["마름모 띠","문짝 위아래를 금 바탕의 마름모 무늬가 둘러쌉니다."]]},"liberale":{"title":"체스 두는 사람들","artist":"리베랄레 다 베로나","date":"1475년경","place":"이탈리아(베로나)","game":"체스","medium":"나무판에 템페라","size":"34.9×41.3cm","credit":"메이틀랜드 F. 그릭스 유증, 1943년","p":["르네상스 이탈리아에서 신부의 혼수를 담던 장식 상자 ‘카소네’ 앞면을 꾸몄던 판화(板畫)의 조각입니다. 화가 리베랄레는 시에나 대성당 성가집의 삽화로도 알려져 있습니다.","이름을 알 수 없는 사랑 이야기의 한 장면입니다. 다른 조각에서는 창가의 아가씨가 젊은이를 안으로 부르는 듯하고, 이 그림에서는 두 사람이 체스를 두고 있습니다. 미술관 해설에 따르면 아가씨가 곧 질 참입니다. 체스는 당시 사랑 문학에서 밀고 당기기를 나타내는 단골 소재였습니다."],"spots":[["체스판","빨강과 하양의 판에 검은 말이 놓여 있고, 승부는 막바지인 듯합니다."],["젊은이","판에 손을 뻗은 젊은이. 이번 승부는 그가 이길 것 같습니다."],["아가씨","맞은편에 앉은 아가씨. 다른 조각에서는 창에서 젊은이를 불렀습니다."],["창밖","열린 창 너머로 언덕과 하늘이 보입니다."],["구경하는 젊은이들","팔짱을 끼고 승부를 지켜보는 남자들."],["구경하는 아가씨들","기둥 너머에서 승부를 엿보는 아가씨들."]]},"mirror":{"title":"체스 두는 연인의 거울 상자","artist":"작자 미상","date":"1325~50년","place":"프랑스(파리)","game":"체스","medium":"상아","size":"지름 10.2cm","credit":"J. H. 웨이드 기금 구입, 1940년","p":["손바닥만 한 이 상아 원판은 손거울의 뚜껑이었습니다. 14세기 파리에서는 잘 닦은 금속 거울을 상아판 두 장 사이에 끼워 들고 다녔습니다. 이런 상아 조각은 궁정과 귀족이 즐긴 사치품이었습니다.","휘장을 친 천막 안에서 젊은이와 귀부인이 체스를 두고 있습니다. 중세 이야기에서 체스는 사랑과 전쟁을 함께 뜻했습니다. 두 사람이 트리스탄과 이졸데, 혹은 랜슬롯과 귀네비어라는 설도 있지만 확실하지 않습니다. 미술관은 묻습니다. 누가 이기고 있는 것 같나요?"],"spots":[["체스판","외다리 탁자 위의 판. 말이 몇 개 서 있습니다."],["젊은이","손을 뻗어 다음 수를 두려 합니다."],["귀부인","두건을 쓴 귀부인. 손끝이 판 위의 말에 닿아 있습니다."],["쥔 손","다른 손은 쥔 채 무릎 위에. 잡은 말을 쥐고 있는 걸까요?"],["천막의 휘장","양쪽으로 묶은 휘장. 체스 장면을 새긴 거울 상자에 흔한 무대입니다."]]},"morris":{"title":"뮐레(나인 멘스 모리스) 판","artist":"페터 플뢰트너","date":"1500~46년","place":"독일","game":"나인 멘스 모리스","medium":"목판화","credit":"찰스 W. 하크니스 기금, 1923년","p":["르네상스 시대 뉘른베르크에서 활약한 조각가 페터 플뢰트너의 목판화입니다. 그는 장식 도안, 가구, 금세공의 원형, 풍자로 유명한 카드 디자인으로도 알려져 있습니다. 소용돌이치는 덩굴무늬 아래 숨어 있는 것은 독일에서 ‘뮐레’라 부르는 나인 멘스 모리스의 판. 세 겹의 정사각형을 변의 가운데에서 이은 모양입니다.","판의 점은 24개. 자기 말 3개를 한 줄로 세우면(밀) 상대 말을 하나 잡습니다. 이런 판화는 장인의 본보기가 되기도 했고, 미술관은 이 한 장을 금세공 원형과 도안 전시에 내놓았습니다. 종이 그대로 놀았는지, 나무나 금속에 옮겼는지는 기록이 없습니다."],"spots":[["가운데 정사각형","가장 안쪽 정사각형. 촘촘한 덩굴무늬로 채워져 있습니다."],["바깥 모서리","바깥 정사각형의 모서리. 말을 놓는 24개 점 가운데 하나입니다."],["가운데 모서리","가운데 정사각형의 모서리도 말을 놓는 점입니다."],["잇는 선","세 정사각형을 변의 가운데에서 잇는 띠. 말은 이 위로도 움직입니다."],["가면","위아래 좌우에 소용돌이 장식틀과 얼굴. 르네상스다운 그로테스크 장식입니다."],["포도 덩굴 테두리","잎과 열매가 검은 바탕에 하얗게 새겨져 있습니다."]]},"leifeng":{"title":"뇌봉탑 놀이판","artist":"작자 미상","date":"1736~95년(건륭 연간)","place":"중국","game":"말판 경주 놀이","medium":"목판화, 종이에 먹","size":"31×29.8cm","credit":"J. H. 웨이드 기금 구입, 2025년","p":["청나라 건륭제 시대에 찍은, 놀이용 한 장짜리 판화입니다. 칸마다 중국 민담 『백사전』의 인물이 그려져 있습니다. 흰 뱀의 정령 백낭자(백낭), 그 짝 소청, 젊은이 허선(뒤의 판본에서는 허선 許仙), 그리고 마지막에 백낭자를 서호 가의 뇌봉탑 아래 가두는 승려 법해입니다.","길은 ‘기마(起馬)’라고 적힌 칸에서 소용돌이를 그리며 가운데 탑으로 향합니다. 서양의 거위 게임처럼 주사위로 이야기를 따라 겨루었을 것입니다. 놀이법은 기록이 남아 있지 않습니다. 미술관에 따르면 이런 색판화 한 장은 도시에서 팔려 벽에 걸리는 도시 문화가 되었고, 색마다 따로 판목을 새겨 찍었습니다."],"spots":[["기마","‘기마’라고 적힌 칸. 여기가 출발점으로 보입니다."],["백낭과 소청","흰 뱀의 정령 백낭자와 그 짝 소청."],["허선","백낭자와 맺어지는 젊은이."],["법해 선사","백낭자를 탑 아래 가두는 승려."],["뇌봉탑","항저우 서호의 뇌봉탑. 이야기가 끝나는 무대입니다."],["가운데","탑 앞에 앉은 여인과 무릎 꿇은 남자. 이야기의 마지막 장면이며, 여기가 도착점일까요?"]]},"tutinama":{"title":"체스 친구인 왕자의 손을 무는 원숭이(『투티나마(앵무새 이야기)』에서)","artist":"다사반타","date":"1560년경","place":"인도(아크바르의 무굴 궁정)","game":"체스","medium":"종이에 구아슈·먹·금","size":"20×14.2cm(그림 부분 10.2×10.6cm)","credit":"A. 딘 페리 부인 기증, 1962년","p":["무굴 제국 아크바르 황제의 궁정에서 만든 이야기책 『투티나마(앵무새 이야기)』의 삽화입니다. 엄마 앵무새가 새끼들에게 여우 새끼 같은 다른 종류의 동물과 친하게 지내지 말라고 일러 주며 들려주는 이야기 가운데 하나로, 체스를 잘 두는 원숭이가 늘 왕자와 체스를 두었습니다.","어느 날 왕자가 손님을 초대한 자리에서 원숭이가 무례한 농담을 하자 왕자가 뺨을 때렸고, 원숭이는 왕자의 손을 물었습니다. 오른쪽 바깥에서는 하인들이 음식을 준비하고 손님들은 놀라서 바라봅니다. 아래 글씨에는 훗날 무굴 궁정에서 가장 이름난 화가가 되는 다사반타의 이름이 있습니다. 젊은 그는 그림 밑에 시원한 파란색을 한 겹 깔았다고 합니다."],"spots":[["원숭이","왕자의 손을 무는 원숭이. 왕자의 체스 친구였습니다."],["왕자","손을 물린 왕자."],["체스판","바닥에 놓인 빨간 칸의 판."],["놀란 손님들","잔치에 초대된 손님들."],["음식 준비","밖에서 솥을 불에 올리는 하인들."],["페르시아어 본문","위 칸에는 이야기가 페르시아어로 쓰여 있습니다."]]},"teniers":{"title":"백개먼 승부","artist":"다비트 테니르스","date":"1640년대","place":"플랑드르","game":"백개먼","medium":"나무판에 유채, 캔버스로 옮김","size":"59×80.6cm","credit":"새뮤얼 D. 와이즈 부부 기증, 1943년","p":["플랑드르 화가 테니르스가 그린, 큰돈이 걸린 백개먼 승부입니다. 백개먼은 역사가 길어 지금의 형태는 1400년대에 나타났고, ‘백개먼’이라는 이름은 바로 이 그림 무렵에 생겼다고 합니다. 1600년대에 크게 유행해 돈을 걸고 자주 했습니다.","두 대국자 둘레에 구경꾼이 모여 있고, 벽 쪽에서는 점수를 적는 사람도 있습니다. 창문으로 내다보는 여인 등을 근거로 미술관은 이곳을 유곽의 놀이방으로 봅니다. 이런 놀이 장면에는 도박은 어리석고 나쁜 일이며 시간 낭비라는 교훈이 담기곤 했습니다."],"spots":[["판","탁자 위에 펼친 백개먼 판. 승부가 진행 중입니다."],["흰 셔츠의 남자","등을 보인 대국자. 말에 손을 뻗고 있습니다."],["턱을 괸 남자","맞은편 대국자. 턱을 괴고 생각에 잠겨 있습니다."],["점수 적는 사람","벽의 판에 표시를 하는 남자. 점수일까, 판돈일까?"],["창가의 여인","창에서 승부를 내려다보는 나이 든 여인."],["안쪽 방","안쪽 방에서는 젊은 여인 곁에서 남자들이 술을 마십니다."]]},"imari":{"title":"바둑 두는 두 사람의 각접시","artist":"작자 미상","date":"1700년대","place":"일본(에도 시대)","game":"바둑","medium":"자기, 틀 성형, 상회(히젠, 이마리 양식)","size":"2.4×13.8cm","credit":"세버런스 앤드 그레타 밀리킨 컬렉션, 1964년","p":["손바닥만 한 각접시에 소나무 아래서 바둑을 두는 두 사람이 그려져 있습니다. 노란 옷의 사람은 땅에 바로 놓은 판을 마주하고 앉았고, 초록 옷의 상대는 나무에 기대어 있습니다.","히젠(지금의 사가·나가사키)에서 구운 이마리 자기로, 초록 색감은 구타니 색회를 떠올리게 한다고 합니다. 일본이 중국을 대신해 유럽 수출 자기의 주된 공급처가 되었을 무렵 수출용으로 만든 물건입니다."],"spots":[["바둑판","칸을 그린 바둑판. 땅에 바로 놓여 있습니다."],["노란 옷의 사람","판을 마주하고 앉은 사람."],["초록 옷의 사람","나무에 기대어 웃는 상대."],["소나무","머리 위로 가지를 뻗은 소나무."],["빨간 테두리","모서리를 자른 빨간 테두리가 그림을 두릅니다."]]},"shoei":{"title":"금기서화도 병풍(한 쌍 중 한 폭)","artist":"전 가노 쇼에이","date":"1500년대 말~1600년대 초","place":"일본(모모야마 시대)","game":"바둑","medium":"6폭 한 쌍 중 하나, 종이에 수묵담채","size":"153×358.6cm","credit":"존 L. 세버런스 기금, 1979년","p":["가노파 화가 가노 쇼에이의 작품으로 전하는 6폭 병풍입니다. 짝을 이루는 다른 한 폭과 함께, 중국 문인이 갖춰야 할 교양 ‘금기서화’ — 거문고를 타고, 바둑을 두고, 글씨를 쓰고, 그림을 그리는 일 — 를 그렸습니다. 소나무 아래 들판에서 지체 높은 중국 신사들이 시종을 거느리고 쉬고 있습니다.","가운데에서는 두 사람이 바둑을 두고 또 한 사람이 지켜봅니다. 곁의 탁자에는 책과, 아직 천 주머니에 든 금(琴)이 놓여 연주를 기다립니다. 즐거움과 격식이 균형을 이룬 장면입니다. 미술관에 따르면 시종 하나는 물속 물고기의 움직임에 정신이 팔려 있습니다."],"spots":[["바둑판","다리가 달린 바둑판. 두 신사가 마주 앉아 둡니다."],["신사들","바둑을 두는 두 사람과 지켜보는 한 사람."],["탁자 위","책과 주머니에 든 금이 놓인 탁자로 보입니다."],["시종들","탁자 곁에서 시중드는 시종."],["물고기에 한눈판 시종","물가에 엎드려 물고기를 보는 시종."],["소나무","화면 위로 가지를 크게 뻗은 소나무."]]},"umaya":{"title":"마구간 그림 병풍(툇마루의 바둑과 쇼기)","artist":"작자 미상","date":"1500년대 전반","place":"일본(무로마치 시대)","game":"바둑·쇼기","medium":"6폭 한 쌍 중 한 점. 종이에 채색·금","size":"146.1×346.6cm","credit":"에드워드 L. 휘트모어 기금 구입, 1934년","p":["6폭을 이은 병풍으로, 좌우 두 점이 한 쌍을 이루는 가운데 하나입니다. 마구간에 매인 귀한 말들이 주제이지만, 앞쪽 툇마루에서도 떠들썩한 일이 벌어지고 있습니다.","툇마루에서는 사람들이 두 가지 게임으로 승부를 겨룹니다. 왼쪽은 바둑, 오른쪽은 쇼기입니다. 미술관의 해설에 따르면 날뛰는 말과 차분히 수를 읽는 판 위의 승부가 어우러져 장면에 활기를 줍니다. 일본에서는 원숭이가 말을 지켜 준다고 여겨 마구간에서 원숭이를 기르기도 했습니다."],"spots":[["바둑판","촘촘한 줄 위에 검은 돌이 놓인 바둑판."],["에보시를 쓴 두 사람","검은 에보시를 쓴 남자들. 초록 옷의 남자가 판으로 손을 뻗고, 붉은 옷의 남자가 곁에서 봅니다."],["쇼기판","칸이 큰 판. 바둑판과 비교하면 칸 수가 훨씬 적습니다."],["웃는 상대","삭발한 승려가 말을 집고, 맞은편 남자는 머리에 손을 얹고 크게 웃습니다. 누가 한 수 이긴 걸까요?"],["원숭이","툇마루 끝에 붉은 옷을 입은 원숭이일까요?"],["말","앞다리를 들고 날뛰는 검은 말. 줄에 매여 있습니다."]]},"goryeo":{"title":"바둑 두는 인물무늬 상감 청자 주전자","artist":"작자 미상","date":"1200년대","place":"한반도(고려)","game":"바둑","medium":"청자, 백토·흑토 상감","size":"높이 20.4cm, 지름 14.3cm","credit":"존 L. 세버런스 기증, 1917년","p":["고려 청자 주전자(주둥이와 손잡이가 있는 그릇)입니다. 그릇에 선을 새겨 흰 흙과 검은 흙을 메우고 유약을 입혀 굽는 ‘상감’은 고려 도공의 장기였습니다. 둥근 틀 안에 버드나무 아래 앉은 두 사람이 하얗게 떠오릅니다.","두 사람 사이에는 판이 있고, 미술관은 이 장면을 바둑 두는 모습에 견줍니다. 거문고·바둑·글씨·그림의 ‘사예’는 문인이 갖추어야 할 교양으로 여겨졌고, 그 우아한 모임은 공예품의 무늬가 되기도 했습니다. 인물을 나타낸 고려 상감 청자는 드뭅니다."],"spots":[["판","두 사람 사이의 판. 흰 흙으로 네모나게 나타냈습니다."],["왼쪽 사람","판을 향해 앉은 사람."],["오른쪽 사람","맞은편에 앉은 상대."],["버드나무","두 사람 머리 위로 늘어진 버들가지. 검은 흙으로 그렸습니다."],["구름 틀","둥근 틀 둘레를 소용돌이치는 구름 같은 무늬가 두릅니다."],["빙렬","유약 표면의 잔금(빙렬). 구운 뒤 식을 때 흙과 유약이 줄어드는 정도가 달라서 생깁니다."]]},"kangra":{"title":"테라스에서 차우파르를 하는 두 사람","artist":"작자 미상","date":"1790~1800년경","place":"인도(파하리, 캉그라파)","game":"차우파르","medium":"소묘, 붉은 오커 밑그림","size":"19.4×13.2cm","credit":"에드워드 L. 휘트모어 기금 구입, 1936년","p":["히말라야 기슭 파하리 지방, 캉그라 화가의 소묘입니다. 붉은 선(붉은 오커 안료)으로 밑그림을 그리고 그 위를 검은 선으로 다듬었습니다. 색을 칠하지 않아 선의 흐름과 사람·도구의 형태가 잘 보입니다.","테라스에 앉은 남녀가 십자형 판을 사이에 두고 차우파르를 합니다. 차우파르는 파치시와 같은 십자형 판을 쓰는 인도의 오래된 경주 게임으로, 긴 주사위(파사)를 던져 말을 움직입니다. 판에는 아직 칸이 그려져 있지 않습니다. 두 사람 곁에서 시녀들이 시중을 듭니다."],"spots":[["십자형 판","바닥에 놓인 십자형 판. 칸은 아직 그려져 있지 않습니다."],["여성","손바닥을 위로 한 여성. 주사위를 던지려는 걸까요?"],["남성","깃 장식을 단 터번의 남성. 판 쪽으로 손을 뻗습니다."],["왼쪽 시녀","작은 병을 들고 천을 내밀고 있습니다."],["오른쪽 시녀","자루가 긴 도구와 작은 그릇을 들고 있습니다."],["붉은 밑그림","터번 둘레에 검은 선 아래의 붉은 밑그림이 보입니다."]]},"vuillard":{"title":"체커 한 판 (『풍경과 실내』 중에서)","artist":"에두아르 뷔야르","date":"1899년","place":"프랑스","game":"체커","medium":"다색 석판화(제3스테이트). 인쇄 오귀스트 클로, 발행 앙브루아즈 볼라르","size":"화면 33×25.7cm(종이 38×30.8cm)","credit":"해나 기금 기증, 1951년","p":["화상 앙브루아즈 볼라르는 판화 발행인이기도 했습니다. 1895년 보나르에게 12점의 컬러 석판화 화집을 맡긴 것을 시작으로 화집을 잇달아 냈고, 뷔야르의 『풍경과 실내』도 그중 하나입니다. 인쇄는 명인 오귀스트 클로가 맡았습니다.","보나르와 뷔야르는 ‘나비파’(히브리어로 ‘예언자’)라 불린 화가 모임의 일원으로, 형태와 색 자체로 감정을 표현하는 새로운 그림을 추구하며 도시의 삶과 가족의 일상을 즐겨 그렸습니다. 무늬로 가득한 방에서 두 남자가 체커판을 사이에 두고 마주 앉고, 한 여성이 선 채로 승부를 지켜봅니다. 프랑스어로 체커는 ‘담(dames)’이며, 왼쪽 아래의 연필 글씨는 ‘partie de dames(체커 한 판)’로 읽힙니다."],"spots":[["판","작은 체크무늬 판. 말이 놓여 있는 것이 보입니다."],["왼쪽 남자","수염 난 남자가 판 위로 손을 뻗습니다."],["오른쪽 남자","안락의자에서 고개를 숙여 판을 보는 상대. 서 있는 여성에게 반쯤 가려져 있습니다."],["서 있는 여성","턱에 손을 괴고 승부를 지켜봅니다."],["램프","벽가의 램프. 벽지도 의자 천도 무늬로 가득합니다."],["연필 글씨","왼쪽 아래에 연필로 ‘partie de dames(체커 한 판)’라고 쓰여 있습니다."]]},"talbot":{"title":"체스 두는 사람들(초기 사진)","artist":"윌리엄 헨리 폭스 탤벗(으로 전함)","date":"1843~47년경","place":"영국","game":"체스","medium":"염화은 인화지 사진(솔트 프린트)","size":"19.9×15cm","credit":"에버렛 코블러 부부 기금 구입","p":["탤벗이 고안한 ‘네거티브-포지티브법’은 한 장의 네거티브로 사진을 몇 장이든 인화할 수 있게 하여, 디지털 시대까지 사진의 기본이 되었습니다. 그의 초기 실험에는 과학에 대한 관심과 예술적 포부가 함께 드러납니다. 연구에 따르면 그는 체스 두는 사람들의 사진을 10장 넘게 찍었습니다.","다만 이 한 장은 탤벗 본인의 작품이 아닐 수도 있습니다. 같은 장면의 사진에는 서명이 없고, 종이도 그가 늘 쓰던 것과 다릅니다. 찍힌 사람은 사진가 앙투안 클로데와 탤벗의 조수 니콜라스 헤네만으로 보이며, 클로데의 스튜디오에서 찍은 사진이 헤네만에게 갔다가 빚을 갚는 대가로 탤벗에게 넘어갔다는 설이 있습니다(미술관 해설)."],"spots":[["판","탁자 위의 체스판. 말이 줄지어 놓여 있습니다."],["실크해트의 남자","모자를 쓴 채 말에 손을 대고 있습니다."],["생각에 잠긴 남자","턱에 손을 괴고 판을 응시하는 상대."],["휘장","뒤에 드리운 휘장. 촬영용 배경일까요?"],["또 하나의 모자","오른쪽 받침 위에 실크해트가 하나 더 놓여 있습니다."]]},"pvl":{"title":"주사위 놀이를 하는 남자들","artist":"PVL의 거장","date":"1520년경","place":"네덜란드","game":"주사위","medium":"종이에 동판화(인그레이빙)","size":"9.4×9.4cm(원형)","credit":"찰스 해크·헌 가족 신탁 컬렉션, 2023년 구입","p":["16세기 초 네덜란드에서 활동한, 이름이 알려지지 않은 동판화가의 작품입니다. 왼쪽 아래에 ‘PVL’ 모노그램이 새겨져 있어 ‘PVL의 거장’이라 불립니다. 손바닥만 한 둥근 판화에 가는 선을 빽빽이 새겨 방의 깊이와 옷의 질감을 나타냈습니다.","탁자 위에는 주사위 두 개. 몸을 내민 남자와 모피 깃의 젊은이가 손가락으로 가리키며 무언가를 다툽니다. 눈의 수를 두고 다투는 걸까요? 뒤에서는 여인들이 승부를 들여다보고, 탁자 아래에는 술 항아리가 놓여 있습니다. 주사위는 예로부터 도박과 이어져 여러 번 금지되었습니다."],"spots":[["주사위","탁자 위를 구르는 주사위 두 개."],["가리키는 손","두 사람의 손가락이 탁자 위에서 맞닿습니다. 눈의 수를 두고 다투는 걸까요?"],["챙 넓은 모자의 남자","몸을 내민 남자. 트임을 넣은 부푼 소매는 당시 유행하던 옷입니다."],["모피 깃의 젊은이","큰 모자와 모피 깃의 젊은이."],["구경하는 여인들","뒤에서 승부를 들여다보는 여인들."],["모노그램","왼쪽 아래의 ‘PVL’. 이 화가의 이름을 알려 주는 유일한 단서입니다."]]},"kiyohiro":{"title":"쌍륙을 두는 사람들","artist":"도리이 기요히로","date":"1750년경","place":"일본(에도 시대)","game":"반스고로쿠(쌍륙)","medium":"베니즈리에(다색 목판, 오반). 판원 우로코가타야","size":"43.5×29.3cm","credit":"클래런스 버킹엄 컬렉션","p":["도리이 기요히로는 1737년경부터 1776년경까지 활동한 우키요에 화가입니다. 이 그림은 ‘베니즈리에’로, 연지(베니)와 초록 등 적은 수의 색판을 겹쳐 찍은 것입니다. 여러 색을 겹치는 ‘니시키에’가 1765년에 등장하기 전의 색감입니다.","검은 받침의 판에서 두는 것은 반스고로쿠(쌍륙)입니다. 두 사람이 주사위를 던져 흰 말과 검은 말을 움직이고, 먼저 자기 말을 모두 빼낸 쪽이 이깁니다. 서양의 백개먼과 같은 계열의 게임으로, 우키요에에는 여인들이 쌍륙을 즐기는 모습이 자주 그려졌습니다. 뒤의 여인은 담뱃대를 물고 승부를 지켜봅니다."],"spots":[["판","받침이 달린 쌍륙판. 흰 말과 검은 말이 놓여 있습니다."],["왼쪽 인물","판으로 손을 뻗어 말을 움직입니다."],["오른쪽 여인","판에 몸을 숙여 말을 바라보는 상대."],["담뱃대의 여인","긴 담뱃대를 물고 뒤에서 승부를 지켜봅니다."],["든 손","오른쪽 여인이 검고 작은 것을 들고 있습니다. 주사위를 흔드는 통일까요?"],["서명","‘鳥居清廣筆’ 서명과 판원 우로코가타야의 인장."]]},"ingram":{"title":"중국 장기(샹치)","artist":"존 잉그럼(부셰의 원화에 따름)","date":"1741~63년","place":"프랑스(파리)","game":"샹치","medium":"에칭과 인그레이빙","size":"종이 39.4×27.7cm(판 24.5×16.4cm)","credit":"엘리샤 휘틀지 컬렉션, 1966년","p":["프랑스 화가 프랑수아 부셰의 소묘를 런던 태생의 판화가 존 잉그럼이 동판으로 옮긴 작품입니다. 잉그럼은 파리로 건너가 1741년부터 1763년까지 부셰의 ‘시누아즈리’(유럽인이 상상한 중국풍) 그림을 잇달아 판화로 만들었습니다. 아래의 제목은 ‘LE JEU D'ECHETS CHINOIS(중국 장기)’입니다.","머리를 높이 묶은 여인이 무릎 위의 판에서 말을 움직이고, 곁에서 어린아이가 지켜봅니다. 이 게임은 중국의 샹치로 여겨지지만, 진짜 샹치의 말은 모두 납작한 원판인데 여기에는 키 큰 말과 작은 네모 말이 놓여 있습니다. 야자나무와 항아리 위에 앉은 인물상도 실제 중국이라기보다 당시 유럽이 꿈꾸던 먼 나라의 모습입니다."],"spots":[["판과 말","무릎 위의 판. 키 큰 말과 네모난 말이 놓여 있습니다. 진짜 샹치의 말은 납작한 원판입니다."],["말을 집는 손","여인의 오른손이 말을 움직입니다."],["턱 괸 팔","왼손을 턱에 대고 판을 내려다봅니다."],["들여다보는 아이","판 곁에 서서 승부를 지켜보는 아이."],["항아리 위의 상","큰 항아리 위에 책상다리로 앉은 인물상."],["제목과 이름","‘부셰 그림’ ‘잉그럼 새김’과 제목 ‘LE JEU D'ECHETS CHINOIS’."]]},"posada":{"title":"거위 놀이","artist":"호세 과달루페 포사다","date":"1909년","place":"멕시코","game":"거위 놀이","medium":"아연 볼록판, 종이","size":"29.3×39.4cm","credit":"윌리엄 매컬린 매키 기념 기금","p":["해골 그림 ‘칼라베라’로 유명한 멕시코의 판화가 포사다가 멕시코시티의 출판업자 안토니오 바네가스 아로요를 위해 만든, 놀이용 한 장짜리 인쇄물입니다. 왼쪽 아래 띠에 ‘JUEGO DE LA OCA(거위 놀이)’라고 쓰여 있고, 1번 칸에서 중심의 63까지 소용돌이를 그리며 나아갑니다.","가운데에는 놀이 방법(EXPLICACION)이 인쇄되어 있습니다. 첫 번째로 5와 4가 나오면 26으로, 6과 3이 나오면 53으로. 거위(새) 칸에 멈추면 같은 수만큼 한 번 더 가고, 19의 여관(Venta)에서는 두 번 쉬며, 31의 우물(Poso)과 52의 감옥(Carcel)은 다른 사람이 올 때까지 나갈 수 없고, 42의 미로에서는 39로, 58의 죽음(Muerte)에서는 처음으로 돌아갑니다. 63에 딱 맞게 도착해야 이깁니다. 특정 칸에 멈추면 판돈을 내는 규칙도 있어 내기 놀이이기도 했습니다."],"spots":[["놀이 방법","가운데의 ‘EXPLICACION’. 칸마다의 규칙과 판돈 내는 법이 적혀 있습니다."],["1번 칸","출발점. 여기서 소용돌이를 그리며 중심으로 갑니다."],["우물(31)","분수 같은 우물. 빠지면 다른 사람이 올 때까지 나갈 수 없습니다."],["죽음(58)","해골 칸. 멈추면 처음으로 돌아갑니다."],["제목 띠","왼쪽 아래 띠에 ‘JUEGO DE LA OCA’. 그 아래서 아이들이 놀고 있습니다."],["출판업자의 이름","여신이 든 띠에 ‘IMPRENTA DE A. VANEGAS ARROYO’. 포사다의 판화를 많이 낸 출판사입니다."]]},"jintile":{"title":"판 놀이를 하는 여인들의 타일","artist":"작자 미상","date":"1200년대","place":"중국(금)","game":"판 놀이(바둑으로 보임)","medium":"토기(틀로 찍은 부조)","size":"높이 27.3cm, 너비 24.8cm, 두께 5.4cm","credit":"아시아 미술 후원회 기금 구입, 2002년","p":["중국 북부를 다스린 여진족의 왕조 금(1115~1234년) 시대에 구운 부조 타일입니다. 꽃이 핀 나무 아래 단 위에 두 여인이 마주 앉아 있고, 그 사이에 판이 놓여 있습니다.","판에는 촘촘한 칸이 새겨져 있어 바둑을 두는 모습으로 보입니다. 오른쪽 여인은 몸을 내밀어 판 위를 가리키고, 왼쪽 여인은 그것을 바라봅니다. 금 시대 중국 북부의 무덤에는 일상생활을 부조한 벽돌로 벽을 꾸민 예가 많이 알려져 있어, 이 타일도 그런 무덤을 꾸몄던 것으로 보입니다."],"spots":[["판","칸이 촘촘한 판. 바둑판으로 보입니다."],["가리키는 손","오른쪽 여인이 판 위를 가리킵니다. 다음 수일까요?"],["왼쪽 여인","머리를 높이 올리고 판을 바라보는 상대."],["오른쪽 여인","몸을 내밀어 판으로 향한 여인."],["꽃나무","두 사람 머리 위로 꽃 핀 나뭇가지가 펼쳐집니다."],["단","두 사람이 앉은 단. 다리 사이에 물결 모양 장식이 있습니다."]]},"kyosai":{"title":"방귀가 바둑판을 뒤엎다(화첩 중에서)","artist":"가와나베 교사이","date":"1800년대 중후반","place":"일본(에도~메이지 시대)","game":"바둑","medium":"26면 접이식 화첩 중 한 장면. 종이에 수묵담채","size":"화첩(접은 상태) 28×18cm","credit":"앤·앤서니 도페이 기증(에번 터너를 기리며)","p":["막부 말기부터 메이지 시대에 걸쳐 활약한 화가 가와나베 교사이(1831~1889년)의 화첩 한 장면으로, 접이식 화첩에 붓 가는 대로 빠르게 그은 먹선으로 그렸습니다. 교사이는 가노파의 탄탄한 기량을 갖추고도 요괴 그림, 희화, 풍자화로 인기를 모았습니다.","미술관이 붙인 제목이 모든 것을 말해 줍니다. ‘방귀가 바둑판을 뒤엎다’. 왼쪽의 에보시 쓴 남자가 몸을 숙인 끝에, 오른쪽에서는 바둑판이 공중에 날고 바둑통에서 돌이 비처럼 쏟아지며 상대 남자는 벌러덩 넘어졌습니다. 진지한 대국을 단 한 방에 망쳐 버리는 우스꽝스러움. 옛 두루마리 그림에도 나오는 ‘방귀’ 웃음을 교사이다운 빠른 붓으로 그렸습니다."],"spots":[["에보시를 쓴 남자","몸을 숙여 엉덩이를 내민 남자. 소동의 원인일까요?"],["날아가는 바둑판","줄이 그어진 바둑판이 비스듬히 날아갑니다."],["바둑통과 돌","바둑통 두 개가 뒤집혀 돌이 쏟아집니다."],["부채","바둑판 곁에서 펼친 부채도 날아갑니다."],["넘어진 상대","벌러덩 넘어져 눈을 휘둥그레 뜬 남자."],["붓의 선","밑그림 없이 단숨에 그은 듯한 힘찬 먹선."]]},"yokuts":{"title":"도박 놀이 쟁반","artist":"요쿠츠족 직조공(이름 미상)","date":"1900년경","place":"미국(캘리포니아주 던랩 부근)","game":"후추이시(호두 껍데기 주사위)","medium":"식물 섬유(코일 짜기)","size":"높이 5.1cm, 지름 61cm","credit":"레너드 S. 플로샤임 주니어 부인 기금 구입","p":["캘리포니아의 많은 원주민은 운에 맡기는 놀이를 즐겼습니다. 이 쟁반은 여성만 하던 주사위 놀이 ‘후추이시’에 쓰였습니다. 호두 껍데기 주사위 8개를 쟁반 위에 던지고, 점수는 막대로 셌습니다.","쟁반에 짜 넣은 둥근 무늬에는 그 놀이 자체, 곧 주사위와 점수 막대와 노는 사람들이 표현되어 있습니다(미술관 해설). 놀이 도구에 그 놀이의 그림을 담은 물건입니다. 사진에는 쟁반 위와 둘레에 호두 껍데기 주사위가 놓여 있습니다."],"spots":[["노는 사람들","가장자리를 따라 늘어선 사람 모습. 놀이에 참여하는 사람들입니다."],["점수 막대","짧은 세로선 묶음. 점수를 세는 막대를 나타냅니다."],["둥근 무늬","작은 둥근 무늬. 주사위를 나타낸 걸까요?"],["호두 주사위","호두 껍데기 주사위. 8개를 쟁반에 던졌습니다."],["삼각형 띠","짙은 삼각형을 잇댄 띠가 한 바퀴 두릅니다."],["가운데","가운데서 소용돌이치는 짜임과 그것을 두른 고리 무늬."]]},"hokkei":{"title":"우시와카마루, 쌍륙으로 벤케이를 이기다","artist":"도토야 홋케이","date":"1825년경","place":"일본(에도 시대)","game":"반스고로쿠(쌍륙)","medium":"스리모노(시키시판 다색 목판)","size":"21.8×19.1cm","credit":"헬렌 C. 건솔러스 기증","p":["가쓰시카 호쿠사이의 제자 도토야 홋케이(1780~1850년)의 스리모노입니다. 스리모노는 교카 동호회 등이 자신들의 노래를 넣어 특별히 찍게 한 판화로, 시판 우키요에보다 좋은 종이와 금속 안료를 써서 호화롭게 만들었습니다.","영웅 미나모토노 요시쓰네의 어린 시절 이름 우시와카마루와 괴력의 승병 벤케이. 두 사람의 만남이라면 교토 고조 대교의 대결이 유명하지만, 이 스리모노에서는 승부가 쌍륙으로 바뀌었습니다. 소년은 태연히 판 너머에 앉아 있고, 나기나타를 멘 벤케이는 머리를 긁으며 패배를 인정합니다. 비틀어 보는 ‘미타테’ 놀이로 보입니다."],"spots":[["쌍륙판","상자 모양의 쌍륙판. 흰 말과 검은 말이 놓여 있습니다."],["머리를 긁는 벤케이","갑옷 차림의 벤케이가 져서 머리를 긁습니다."],["우시와카마루","판 너머에 앉은 소년 우시와카마루."],["나기나타","벤케이가 멘 큰 나기나타의 날."],["교카","오른쪽 위의 노래. 스리모노를 주문한 동호회의 노래로 보입니다."],["서명","오른쪽 아래 틀 안의 홋케이 서명."]]},"vorsterman":{"title":"백개먼을 하는 사람들(밤 장면)","artist":"루카스 에밀 포르스테르만(아담 더 코스테르의 원화에 따름)","date":"1630년경","place":"플랑드르(안트베르펜)","game":"백개먼","medium":"인그레이빙, 상아색 종이","size":"화면 25.5×34.4cm","credit":"버나드 F. 로저스 컬렉션","p":["아담 더 코스테르는 1630년경 안트베르펜에서 촛불이 비추는 밤 장면으로 이름난 화가였습니다. 같은 무렵 같은 도시에서 포르스테르만은 인기 화가들의 그림을 동판화로 옮기고 있었습니다. 루벤스의 제자였던 그는 스승과 사이가 틀어져 영국으로 건너간 뒤, 명암이 강하고 양식화된 카라바조풍 판화를 만들게 됩니다.","어두운 방의 탁자에서 남자들이 백개먼 판을 둘러싸고 있습니다. 더 코스테르의 빛 처리를 본받아, 두 촛불이 탁자 둘레의 얼굴들을 비춥니다(미술관 해설). 오른쪽에서는 류트를 안은 젊은이가 이쪽을 바라봅니다."],"spots":[["판","탁자 위에 상자처럼 펼친 백개먼 판."],["촛불","촛대의 촛불. 불빛이 사람들의 얼굴을 비춥니다."],["파이프의 남자","챙 넓은 모자의 남자가 파이프를 물고 승부를 봅니다."],["등을 보인 남자","탁자에 손을 짚고 몸을 내민 남자."],["류트의 젊은이","류트를 안고 이쪽에 웃어 보이는 젊은이."],["이름","왼쪽 아래 ‘A. De Coster pi.’, 오른쪽 아래 ‘Vorsterman’."]]},"zorn":{"title":"체스 두는 사람들","artist":"안데르스 소른","date":"1891년","place":"스웨덴","game":"체스","medium":"에칭, 상아색 레이드지","size":"화면 13.5×9.6cm(판 13.9×10cm)","credit":"월리스 L. 디울프·찰스 디어링 소른 에칭 컬렉션","p":["스웨덴 화가 안데르스 소른(1860~1920년)의 에칭입니다. 소른은 유화와 수채 초상화로 국제적 명성을 얻었고, 동판화에서도 큰 작업을 남겼습니다. 손바닥만 한 작은 판입니다.","빠르게 그은 사선을 겹치는 것만으로 어두운 방과 사람의 모습이 떠오릅니다. 앞쪽 남자는 등을 보인 채 판을 들여다보고, 맞은편 인물은 고개를 숙이고 다음 수를 생각합니다. 판 위에는 가는 선으로 말이 그려져 있습니다. 누구를 그렸는지는 기록이 없습니다."],"spots":[["판과 말","아래 밝은 부분이 판. 짧은 세로선이 말입니다."],["앞쪽 남자","등을 보이며 판 위로 몸을 숙인 남자."],["맞은편 사람","고개를 숙이고 판을 바라보는 상대."],["어두운 배경","세로선을 겹쳐 만든 어두운 방 안쪽."],["사선","윗옷은 빠른 사선을 겹쳐 나타냈습니다."],["서명","판 아래에 연필로 ‘Zorn’ 서명."]]},"harunobu-sugoroku":{"title":"승부를 보다(반스고로쿠)","artist":"스즈키 하루노부","date":"1766년경","place":"일본(에도 시대)","game":"반스고로쿠(쌍륙)","medium":"다색 목판(주반, 스리모노)","size":"28.5×21cm","credit":"클래런스 버킹엄 컬렉션","p":["스즈키 하루노부(1725?~1770년)는 여러 색판을 겹쳐 찍는 ‘니시키에’가 1765년경 생겨났을 때 그 중심에 있던 우키요에 화가입니다. 이 그림은 특별히 찍은 스리모노로, 부드럽게 겹친 색에 그 새로움이 드러납니다.","매화가 핀 방에서 두 아가씨가 상자 모양의 쌍륙판을 사이에 두고 놀고, 다른 한 사람은 선 채로 판을 들여다봅니다. 판에는 흰 말과 검은 말이 놓여 있고, 왼쪽 아가씨는 말을 움직이며 오른쪽 아가씨도 판으로 손을 뻗습니다. 뒤의 맹장지에는 폭포와 소나무가 그려져 있습니다."],"spots":[["쌍륙판","상자 모양의 반스고로쿠 판. 흰 말과 검은 말이 놓여 있습니다."],["왼쪽 아가씨","종이학 무늬 기모노. 말을 움직이고 있습니다."],["오른쪽 아가씨","몸을 숙여 판으로 손을 뻗는 상대."],["구경하는 아가씨","선 채로 승부를 들여다보는 아가씨. 손에 긴 자루의 도구를 들었습니다."],["매화","위에서 가지를 뻗은 흰 매화."],["맹장지 그림","폭포와 소나무를 그린 맹장지."]]},"kota":{"title":"크리슈나를 예배하는 코타의 왕 키쇼르 싱 2세","artist":"작자 미상","date":"1825년경","place":"인도(라자스탄, 코타)","game":"파치시","medium":"종이에 고무 템페라, 은, 금","size":"24.5×18.8cm","credit":"제임스 앨버트·메리 가디너 포드 기념 기금","p":["라자스탄의 작은 번왕국 코타의 왕(재위 1819~28년)이 푸슈티 마르그파 사제의 차림으로 다섯 불꽃의 등명을 바칩니다. 제단의 작은 감실에는 크리슈나와 두 왕비의 금속상이 모셔져 있는데, 이 상은 코타에서만 예배됩니다.","천장에는 유리 등이 잔뜩 매달려 있고, 제단으로 오르는 단에는 크리슈나와 동무들을 즐겁게 할 장난감과 놀이 도구가 놓여 있습니다. 놋쇠 코끼리, 은 소, 공, 그리고 파치시 판(미술관 해설). 붉은 십자형 천이 그 판으로, 파치시가 신의 놀잇감으로 바쳐졌음을 알 수 있습니다."],"spots":[["파치시 판","단 위의 붉은 십자형 천. 파치시 판입니다."],["코끼리","놋쇠 코끼리 두 마리가 판 곁에 서 있습니다."],["공","위 단에 놓인 금빛 공."],["크리슈나상","작은 감실에 모신 크리슈나와 두 왕비의 상."],["왕과 등명","사제 차림의 왕이 다섯 불꽃의 등명을 바칩니다."],["유리 등","천장에서 드리운 수많은 유리 등."]]},"coyote":{"title":"코요테 놀이","artist":"호세 과달루페 포사다의 추종자","date":"연대 미상","place":"멕시코","game":"코요테와 암탉(여우와 거위 계열)","medium":"아연 볼록판, 종이","size":"38.2×30.5cm","credit":"윌리엄 매컬린 매키 기념 기금","p":["포사다가 멕시코시티 대중 인쇄소를 위해 만든 것과 같은 아연 볼록판으로 찍은, 놀이용 한 장짜리 인쇄물입니다. 위에 크게 ‘JUEGO DEL COYOTE(코요테 놀이)’라고 쓰여 있고, 둘레에는 닭장을 노리는 코요테와 막대를 휘둘러 쫓는 사람이 그려져 있습니다. 아래 띠에는 ‘일데폰소 T. 오레야나 소유’라고 적혀 있습니다.","아래의 ‘EXPLICACION’에 놀이 방법이 인쇄되어 있습니다. 두 사람이 하며, 한쪽은 암탉 15마리, 다른 쪽은 코요테 1마리. 암탉은 앞과 옆으로만 가고 뒤로는 못 갑니다. 코요테는 어느 방향으로나 움직이며, 바로 뒤가 비어 있으면 암탉을 뛰어넘어 잡아먹습니다. 암탉은 코요테를 에워싸 움직이지 못하게 하면 이깁니다. 유럽의 ‘여우와 거위’와 같은 구조의 몰이 놀이입니다."],"spots":[["코요테의 자리","가운데 원에 그린 코요테 얼굴. 코요테가 여기서 시작합니다."],["암탉의 자리","암탉 그림의 원. 여기에 암탉 말을 놓습니다."],["놀이 방법","‘EXPLICACION’. 말의 수와 움직임, 승패가 적혀 있습니다."],["제목","‘JUEGO DEL COYOTE’ — 코요테 놀이."],["암탉을 노리는 코요테","왼쪽 아래에서 코요테가 암탉을 노립니다."],["막대를 휘두르는 사람","오른쪽 위에서 막대를 들어 코요테를 쫓는 사람."]]},"mons":{"title":"몽스(베르헌)를 건 트릭트랙, 1709년","artist":"피터르 놀페(판 제작·발행)","date":"판 1623~53년, 인쇄 1709년경","place":"네덜란드(암스테르담)","game":"트릭트랙(백개먼 계열)","medium":"에칭, 인그레이빙, 활자로 찍은 시","size":"종이 35.8×18.6cm(판 12.9×17.5cm)","credit":"","p":["네 남자가 탁자에서 트릭트랙을 둡니다. 미술관 기록에 따르면 기호 A~D는 말버러 공작, 바이에른 선제후, 아우베르케르크 경, 빌루아 공작입니다. 1709년 연합군이 프랑스 쪽에서 몽스(네덜란드어로 베르헌)를 포위해 빼앗은 사건을, 도시를 건 판 위의 승부로 빗댄 풍자 판화입니다. 안쪽 방(E)에는 스페인 왕 펠리페 5세가 여인과 있습니다.","판에는 ‘놀페 제작·발행’이라고 되어 있지만 화가 피터르 놀페는 1650년대 초에 세상을 떠났으므로, 17세기의 옛 판에 기호와 새 시를 더해 다시 찍은 것으로 보입니다. 아래의 시는 높으신 분들의 놀이는 tiktak과 verkeer(두 가지 백개먼 계열 놀이)뿐이라고 시작해, 기호마다 승부를 비꼽니다."],"spots":[["판","탁자 위의 트릭트랙 판. 도시를 건 승부입니다."],["A 말버러 공작","선 채로 판을 내려다보는 남자. 연합군을 이끈 영국 장군입니다."],["B 바이에른 선제후","모자를 벗고 의자에 깊이 앉은 남자."],["C 아우베르케르크 경","깃털 모자의 남자. 네덜란드군 장군입니다."],["E 안쪽 방","문 너머 침실에 펠리페 5세와 여인."],["시","아래에 활자로 찍은 네덜란드어 시. A~E마다 승부를 비꼽니다."]]},"stembus":{"title":"투표함 ― 정치 거위 놀이","artist":"요한 미하엘 슈미트 크란스(판화)","date":"1867년","place":"네덜란드","game":"거위 놀이(풍자)","medium":"석판화","size":"66×50cm","credit":"","p":["거위 놀이 모양을 한 풍자 판화입니다. 주간지 『더 네덜란서 스펙타토르』 1867년 3월 2일 자 제9호에 딸려 나왔고, 놀이 방법을 적은 별지도 함께였습니다(미술관 기록). 칸에는 당시 장관들의 초상이 들어 있습니다.","출발은 헤이그의 국회 비넨호프. 도착은 판 한가운데 64번째 칸 ‘인술린더’(네덜란드령 동인도의 아칭)로, 자와섬에 매달린 장관 피터르 메이어르의 초상화가 기다립니다. 메이어르는 식민지 장관에서 동인도 총독이 되었고, 이 인사가 정계에 큰 소동을 일으켰습니다. 보통 63칸인 거위 놀이보다 한 칸 많은 것도 이 결말 때문으로 보입니다."],"spots":[["출발","왼쪽 위의 건물. 헤이그의 비넨호프(국회)에서 시작합니다."],["메이어르의 초상","63번 칸. 액자에 든 피터르 메이어르의 초상이 밧줄로 섬에 매달려 있습니다."],["인술린더 64","가운데 섬과 ‘64’ 글자. 여기가 도착입니다."],["투표함","오른쪽 아래의 ‘DE STEMBUS(투표함)’. 제목이 된 상자입니다."],["장관들","칸의 창에는 당시 장관들의 얼굴이 늘어서 있습니다."],["수탉","칸 안의 수탉. 무엇을 비꼰 것인지는 알려져 있지 않습니다."]]},"koorai":{"title":"판을 둘러싼 조선 사람들(지볼트 『일본』에서)","artist":"제임스 에르크슬레벤(석판), ‘Toioske’의 원화에 따름","date":"1832~52년","place":"네덜란드(레이던) / 조선 사람들","game":"판 놀이(바둑으로 보임)","medium":"톤 석판화, 손 채색","size":"종이 38×55.5cm","credit":"F. G. 발러 기증","p":["독일 태생의 의사 지볼트가 나가사키 네덜란드 상관에 있던 시절(1823~30년)의 견문을 바탕으로 레이던에서 펴낸 대작 『일본(NIPPON)』의 한 장입니다. 오른쪽 위에 ‘TAB. I’, 아래에 ‘KOORAI(고려)’라고 적혀 있고, 네덜란드어와 독일어로 ‘어부 가족’이라고 덧붙였습니다. 석판은 에르크슬레벤이 그렸고, 판에는 원화 작가가 ‘Toioske’로 적혀 있습니다.","네 남자가 땅에 앉아 판을 둘러싸고, 왼쪽에는 아이 손을 잡은 여인, 오른쪽에는 긴 막대와 주머니를 든 남자가 서 있습니다. 앞쪽에는 챙 넓은 검은 갓이 놓여 있습니다. 판에는 칸과 둥근 돌이 그려져 있어 바둑으로 보이지만, 기록에는 ‘판 놀이’라고만 되어 있습니다."],"spots":[["판","칸 위의 둥근 돌. 바둑을 두는 모습으로 보입니다."],["검은 갓","땅에 놓인 챙 넓은 검은 갓."],["어머니와 아이","아이 손을 잡고 승부를 보는 여인."],["서 있는 남자","긴 막대와 주머니를 들고 선 남자."],["몸을 숙인 남자","푸른 저고리의 남자가 판을 들여다봅니다."],["제목","‘KOORAI(고려)’, 네덜란드어와 독일어로 ‘어부 가족’."]]},"cairo":{"title":"카페 앞에서 판을 둘러싼 사람들(카이로)","artist":"델리에 & 베샤르(이폴리트 델리에, 에밀 베샤르)","date":"1869~90년경","place":"이집트(카이로)","game":"판 놀이(체스로 보임)","medium":"알부민 프린트","size":"10.8×16.4cm","credit":"","p":["카이로에서 사진관을 운영한 프랑스 사진가 이폴리트 델리에와 에밀 베샤르의 사진입니다. 대지에는 ‘에즈베키야 정원 옆’이라는 사진관 이름과 ‘카이로(이집트)’가 인쇄되어 있습니다. 이런 사진은 이집트를 찾은 여행자들이 기념으로 샀습니다.","격자창이 있는 가게 앞 땅바닥에 남자들이 앉아 낮은 받침 위의 판을 둘러싸고 있습니다. 판에는 키 큰 말이 여럿 서 있어 체스(아랍어로 샤트란지)로 보이지만, 미술관 기록에는 ‘판 놀이’라고만 되어 있습니다. 촬영을 위해 모두 꼼짝 않고 있습니다."],"spots":[["판과 말","낮은 받침 위의 판. 키 큰 말이 늘어서 있어 체스로 보입니다."],["격자창","나무 격자를 끼운 창. 카이로 옛 집들에 흔한 구조입니다."],["지팡이의 남자","지팡이를 들고 앉아 승부를 보는 남자."],["바구니","땅에 놓인 엮은 바구니."],["구경하는 아이","뒤에서 판을 들여다보는 아이."],["사진관 이름","대지의 ‘AU JARDIN DE L'ESBÉKIEH’와 ‘CAIRE (EGYPTE)’."]]},"vanmour":{"title":"카드놀이를 하는 아르메니아인들의 모임","artist":"장바티스트 반무르","date":"1720~37년경","place":"오스만 제국(이스탄불)","game":"카드놀이","medium":"캔버스에 유채","size":"44.5×58.5cm","credit":"","p":["플랑드르 출신 화가 반무르는 1699년 프랑스 대사를 따라 이스탄불로 건너가 세상을 떠날 때까지 이 도시에 살며 궁정 행사와 사람들의 생활을 그렸습니다. 미술관은 남자들의 옷차림으로 보아 아르메니아인임을 알 수 있다고 적고 있습니다.","커다란 촛불 아래 남녀가 붉은 천을 덮은 탁자에 둘러앉아 카드를 하고 있습니다. 탁자에는 나누어 준 카드가 놓여 있고, 손에 든 패를 들여다보는 사람도 있습니다. 왼쪽 구석에서는 나이 든 여인이 실을 잣고 있습니다. 어떤 놀이인지는 기록에 없습니다."],"spots":[["탁자의 카드","붉은 천 탁자 위에 놓인 카드."],["큰 촛불","모두를 비추는 촛불 하나."],["실 잣는 노파","왼쪽 구석에서 실을 잣는 나이 든 여인."],["패를 보는 여인","오른쪽 끝에서 손패를 보는 여인."],["모피 옷의 남자","모피를 두른 웃옷의 남자. 옷차림으로 아르메니아인으로 봅니다."],["손을 뻗은 사람","탁자로 몸을 내밀어 카드를 든 사람."]]},"algiers":{"title":"판 놀이를 하는 세 남자(알제)","artist":"작자 미상","date":"1851~1900년","place":"알제리(알제)","game":"판 놀이(백개먼으로 보임)","medium":"알부민 프린트","size":"14.0×10.0cm","credit":"","p":["사진 아래에 손글씨로 ‘Alger(알제)’라고 적힌, 작자를 알 수 없는 사진입니다. 무늬 없는 배경 앞에 의자와 작은 탁자를 놓았으니 사진관에서 찍은 것으로 보입니다. 북아프리카 사람들을 담은 이런 사진은 여행자와 수집가들이 샀습니다.","두 남자가 테두리가 있는 판을 사이에 두고 마주 앉았고, 오른쪽 남자가 지금 말에 손을 뻗고 있습니다. 판 위에 둥근 말이 겹쳐 쌓여 있어 백개먼(이 지역에서는 타울라 등으로 부름)으로 보이지만, 기록에는 ‘판 놀이’라고만 되어 있습니다. 앞의 작은 탁자에는 커피 도구가 놓여 있습니다."],"spots":[["판과 말","테두리 있는 판에 둥근 말이 쌓여 있습니다."],["서서 보는 남자","허리에 띠를 두르고 뒤에 서서 승부를 내려다보는 남자."],["왼쪽 노인","머리에 천을 감고 생각에 잠긴 노인."],["오른쪽 남자","머리에 흰 천을 쓰고 판을 들여다보는 남자."],["커피 도구","투각 장식 탁자 위의 쟁반과 작은 잔."],["말을 옮기는 손","막 말을 집으려는 오른쪽 사람의 손."]]},"circo":{"title":"서커스 게임(후에고 델 시르코)","artist":"마누엘 마닐랴(추정)","date":"연대 미상","place":"멕시코","game":"주사위 2개로 하는 내기 놀이","medium":"볼록판(목구목판 또는 사진 제판)·황갈색 종이","size":"26.2×35.0cm","credit":"","p":["멕시코 판화가 마누엘 마닐랴의 작품으로 여겨지는(미술관은 ‘?’ 표시) 놀이용 낱장 인쇄물입니다. 오른쪽 아래에는 판매처인 판화 가게 ‘엘 테아트로’의 이름과 주소가 찍혀 있습니다. 이런 값싼 인쇄물은 거리에서 팔렸고, 오리지 않고 그대로 놀이판으로 쓴 것으로 보입니다.","가운데 서커스 천막이 있고, 둘레에 곡마, 인간 탑, 장사 등의 그림이 늘어서 있으며 저마다 2부터 12까지의 수가 붙어 있습니다. 왼쪽 위 ‘설명’에 따르면 몇 명이든, 아이도 할 수 있고, 주사위 2개를 던져 나온 수의 칸에 판돈을 놓거나 이미 놓인 판돈을 가져갑니다. 12를 던진 사람이 전부를 가져갑니다."],"spots":[["서커스 천막","‘JUEGO DEL CIRCO’ 제목과 12번 칸인 천막."],["놀이 방법 설명","‘ESPLICACION(설명)’으로 시작하는 놀이 방법."],["곡마","달리는 말 등에서 춤추는 곡예사. 6번 칸."],["인간 탑","한 사람의 어깨 위에 선 사람. 4번 칸."],["장사","대포 같은 무게추를 드는 남자. 8번 칸."],["판화 가게 이름","‘De venta, Estampería “El Teatro”’와 주소."]]},"loteria":{"title":"로테리아 그림 카드","artist":"호세 과달루페 포사다","date":"1880~1913년","place":"멕시코","game":"로테리아(그림 부르기 놀이)","medium":"볼록판(목구목판 또는 사진 제판)·황갈색 종이","size":"30.0×40.0cm","credit":"","p":["멕시코 판화가 포사다는 멕시코시티의 출판업자 안토니오 바네가스 아로요를 위해 뉴스, 노래, 놀이를 담은 값싼 인쇄물의 그림을 많이 그렸습니다. 이 한 장에도 ‘JUEGO DE LOTERIA(로테리아 놀이)’라는 제목과 바네가스 아로요의 이름이 찍혀 있습니다.","별, 달, 전갈, 악마, 해골, 수탉, 인쇄소 등 이름이 붙은 작은 그림 38개가 늘어서 있습니다. 로테리아는 빙고와 비슷한 놀이로, 부르는 사람이 카드를 뽑아 그림 이름을 외치면 자기 판에 그 그림이 있는 사람은 콩 등으로 표시합니다. 이 종이는 잘라서 카드로 쓴 것으로 보입니다."],"spots":[["제목과 출판사","‘JUEGO DE LOTERIA’와 바네가스 아로요 가게 이름."],["별","‘ESTRELLA’. 왼쪽 위 첫 그림."],["달","‘LUNA’. 얼굴이 있는 초승달."],["죽음","‘MUERTE’. 큰 낫을 들고 피리를 부는 해골."],["풀케 채집꾼","‘TLACHIQUERO’. 용설란 즙을 모으는 남자."],["인쇄소","‘IMPRENTA’. 인쇄기를 다루는 일꾼들. 이런 인쇄물을 만드는 곳입니다."]]},"jeupol":{"title":"‘폴란드 놀이’, 곧 다마 판","artist":"작자 미상","date":"1833~1900년","place":"벨기에 또는 네덜란드","game":"다마(10×10칸 체커)","medium":"목판, 활판 글자","size":"32.2×39.6cm","credit":"","p":["위쪽에 프랑스어와 네덜란드어로 ‘JEU POLONAIS OF DAMSPEL’이라는 제목이 찍힌 낱장입니다. ‘폴란드 놀이’는 프랑스에서 10×10칸 다마를 부르던 이름입니다. 오른쪽 위에는 출판사의 일련번호 ‘n. 106’이 있습니다.","미술관 기록대로 흑백 50칸씩 모두 100칸이 있고, 좌우에 장식 테두리가 있습니다. 말은 찍혀 있지 않으니 콩이나 단추를 말로 삼아 종이째로 두던 값싼 판이었던 것으로 보입니다. 종이에는 접힌 자국이 남아 있습니다."],"spots":[["제목","‘JEU POLONAIS OF DAMSPEL’ 글자."],["일련번호","출판사 번호 ‘n. 106’."],["왼쪽 장식","둥근 꽃무늬를 세로로 늘어놓은 테두리."],["오른쪽 장식","왼쪽과 같은 무늬."],["100칸","10×10 판. 검은 칸은 가는 선으로 찍혀 있습니다."],["접힌 자국","종이에 남은 접힌 자국. 접어서 가지고 다녔을지도 모릅니다."]]},"dkaart":{"title":"오려 쓰는 도미노와 트럼프","artist":"작자 미상(브레폴스 판)","date":"1800~1833년","place":"벨기에(투른하우트)","game":"도미노와 트럼프","medium":"목판(파랑·빨강·노랑 채색), 활판 글자","size":"34.3×41.9cm","credit":"","p":["미술관 기록에 따르면 오려서 쓰는 트럼프 32장과 도미노 28개를 찍은 한 장입니다. 출판사 브레폴스 목록의 114번이며, 아래에 소매상 ‘D. 푸웰스(베르헌옵좀)’의 이름이 있습니다. 제목은 네덜란드어와 프랑스어로 나란히 적혀 있습니다.","왼쪽에는 0-0부터 6-6까지 도미노 28개가 삼각형으로 쌓여 있습니다. 오른쪽 트럼프는 각 무늬의 7~10과 그림 카드·에이스로 된 32장으로, 피케 같은 놀이에 쓰는 한 벌입니다. 오려지지 않고 남아서 인쇄된 그대로의 모습을 볼 수 있습니다."],"spots":[["제목","‘DOMINO EN KAARTSPEL’ 글자."],["0-0","삼각형 꼭대기, 눈이 없는 도미노."],["6-6","맨 아랫줄 오른쪽 끝의 가장 큰 패."],["스페이드 에이스","왼쪽 줄 위에서 두 번째."],["그림 카드","빨강·파랑·노랑으로 칠한 왕 카드."],["소매상 이름","아래의 ‘D. POUWELS, Bergen-op-Zoom’."]]},"apen":{"title":"트릭트랙을 하는 원숭이 두 마리","artist":"퀴린 불(다비트 테니르스의 원화에 따름)","date":"1635~1690년","place":"플랑드르","game":"트릭트랙(백개먼의 일종)","medium":"에칭","size":"11.0×14.5cm","credit":"","p":["사람의 행동을 원숭이가 흉내 내는 ‘원숭이 그림’ 연작(표제판과 여섯 장) 중 한 장입니다. 왼쪽 아래에 ‘D. 테니르스 원작·간행, 특허’라고 있어, 플랑드르 화가 테니르스의 도안을 퀴린 불이 판화로 만들었습니다.","미술관 기록대로 원숭이 두 마리가 바닥에 앉아 트릭트랙 판을 사이에 두고 있습니다. 왼쪽 원숭이는 유리잔으로 포도주를 마시고, 오른쪽 원숭이는 수탉 깃털을 꽂은 모자를 쓰고 말에 손을 뻗습니다. 술과 노름에 빠진 사람을 비웃는 그림으로 보입니다."],"spots":[["판","바닥에 놓인 접이식 트릭트랙 판. 삼각형 칸과 말이 보입니다."],["왼쪽 원숭이","웃옷을 입고 판 앞에 앉은 원숭이."],["포도주잔","왼쪽 원숭이가 든 잔."],["깃털 모자","오른쪽 원숭이 모자의 수탉 깃털."],["술 단지","왼쪽 원숭이 발치의 단지."],["명문","‘D Teniers in et excud cum privilegio’ 글자."]]},"dstereo":{"title":"탁자에서 도미노를 하는 남자들(입체 사진)","artist":"작자 미상","date":"1850~1880년","place":"미상(네덜란드어 글씨)","game":"도미노","medium":"알부민 프린트(입체 사진)","size":"8.5×17.0cm","credit":"","p":["좌우로 거의 같은 사진 두 장을 나란히 붙인 입체 사진입니다. 전용 안경(스테레오스코프)으로 보면 깊이가 있는 하나의 장면으로 보입니다. 왼쪽 끝에 손글씨로 ‘Het dominospel(도미노 놀이)’이라고 적혀 있습니다.","건물 앞 양지에 탁자를 내놓고 셔츠 차림의 남자들이 도미노 패를 쥐고 있습니다. 두 사람은 서서 판을 들여다보고, 오른쪽 남자는 흰 모자를 썼습니다. 모두 움직이지 않아야 했으니 촬영을 위해 꾸민 장면으로 보입니다."],"spots":[["탁자 위의 패","손에 엎어 쥔 도미노 패."],["흰 모자의 남자","오른쪽에 앉아 패를 든 남자."],["스카프의 남자","목에 스카프를 매고 서서 내려다보는 남자."],["왼쪽 남자","팔꿈치를 괴고 패를 보는 젊은 남자."],["글씨","왼쪽 끝의 손글씨 ‘Het dominospel.’."],["다른 한 장","오른쪽 사진. 조금 비켜서 찍어, 두 장이 함께 입체로 보입니다."]]},"gojo":{"title":"바둑을 두는 두 여인","artist":"작자 미상","date":"1870~1891년","place":"일본","game":"바둑으로 보임","medium":"손으로 채색한 알부민 프린트","size":"9.0×13.5cm","credit":"","p":["흑백 사진에 붓으로 색을 입힌 수채색 사진입니다. 이런 사진은 요코하마 등지의 사진관에서 외국인을 위한 기념품으로 만들어졌습니다. 이 한 장은 마닐라 여행 사진첩에 붙어 있던 것입니다.","도코노마 같은 장식과 병풍을 배경으로 두 여인이 다리 달린 판을 사이에 두고 앉아 있고, 왼쪽 여인이 돌을 놓고 있습니다. 판에 흰 돌과 검은 돌이 있어 바둑으로 보이지만, 미술관 기록에는 ‘판 놀이’라고 되어 있습니다. 앞의 쟁반에는 과자와 그릇이 놓여 있습니다."],"spots":[["판과 돌","다리 달린 두꺼운 판에 흰 돌과 검은 돌."],["돌을 놓는 손","왼쪽 여인이 돌을 놓는 순간."],["왼쪽 여인","이쪽을 돌아보는 여인. 오비를 크게 묶었습니다."],["오른쪽 여인","줄무늬 기모노를 입고 판 곁에 손을 둔 여인."],["쟁반과 그릇","앞에 놓인 과자와 찻잔."],["꽃꽂이","뒤쪽 받침대 위의 꽃병."]]},"meade":{"title":"체스를 두는 두 남자","artist":"찰스 리처드 미드, 헨리 윌리엄 매슈 미드","date":"1852년","place":"미국","game":"체스","medium":"다게레오타입","size":"6.9×8.3cm","credit":"","p":["영국에서 태어나 미국으로 건너간 미드 형제의 사진관이 찍은 다게레오타입입니다. 다게레오타입은 은을 입힌 구리판에 직접 상을 만드는 사진이라 다시 인화할 수 없는 단 한 점이었고, 그래서 금색 틀을 댄 작은 가죽 상자에 넣었습니다.","두 젊은이가 작은 받침 위의 체스판을 사이에 두고, 왼쪽 남자가 말에 손가락을 얹고 있습니다. 오른쪽 남자는 가슴에 손을 얹고 판을 바라봅니다. 오래 움직이지 않아야 했으니 수를 두는 척 잡은 자세로 보입니다."],"spots":[["체스판","꽃무늬 천을 덮은 받침 위의 판과 흰 말."],["왼쪽 남자","말에 손가락을 얹은 남자."],["오른쪽 남자","판을 내려다보는 남자."],["가슴에 얹은 손","오른쪽 남자의 생각에 잠긴 손."],["받침의 천","꽃무늬 천을 덮은 작은 받침."],["금색 틀","상을 지키는 금색 틀과 상자."]]},"weiqidai":{"title":"바둑을 두는 도교 신선이 있는 산수","artist":"전 대진","date":"명대, 15~16세기","place":"중국","game":"바둑(위기)","medium":"족자, 비단에 수묵채색","size":"175.2×106.7cm","credit":"","p":["명나라 화가 대진(1388년경~1462년)의 작품으로 전하는 큰 족자입니다. 저장 출신인 대진은 힘찬 필치의 산수화로 이름났고, 뒤에 ‘절파’의 시조로 꼽혔습니다. 우뚝 솟은 벼랑과 큰 나무 아래에 사람들이 작게 그려져 있습니다.","나무 그늘 땅바닥에 두 신선이 가로세로 줄을 그은 바둑판을 사이에 두고 앉았고, 곁에는 과일 접시와 그릇이 놓여 있습니다. 왼쪽에 웅크린 인물은 산에서 신선의 바둑을 구경하다 도낏자루가 썩을 만큼 세월이 흐른 나무꾼 이야기(‘난가’)를 떠올리게 하지만, 미술관의 제목은 ‘바둑 두는 도교 신선’뿐입니다."],"spots":[["바둑판","테두리가 있는 판에 촘촘한 격자가 그려져 있습니다."],["수염의 신선","긴 수염의 신선. 느긋하게 앉아 판을 봅니다."],["푸른 두건의 신선","판으로 몸을 내민 신선. 무릎 곁에 바둑돌 그릇이 있습니다."],["웅크린 사람","왼쪽에서 판을 들여다보는 인물. 난가의 나무꾼으로도 보입니다."],["과일과 그릇","판 너머에 놓인 접시와 항아리."],["낙관과 인장","오른쪽 위의 서명과 붉은 인장 두 개."]]},"reise":{"title":"세계 일주 여행(물길과 뭍길로)","artist":"작자 미상","date":"19세기","place":"독일어권으로 보임","game":"주사위 1개로 하는 판돈 경주 놀이","medium":"석판화","size":"42.5×33.7cm","credit":"","p":["독일어로 ‘세계 일주 여행, 물길과 뭍길로 — 새롭고 즐거운 주사위 놀이’라는 제목이 붙은 놀이용 낱장입니다. 둥근 판에 1부터 41까지 칸이 있고, 기구, 범선, 증기선, 기차, 여러 나라 사람 등의 그림이 들어 있습니다. 오른쪽 아래에 ‘No. 107’이라는 번호가 있습니다.","아래에는 독일어·영어·네덜란드어·프랑스어로 놀이 방법이 찍혀 있습니다. 참가자는 먼저 15마르크를 공동의 ‘여행 지갑’에 내고, 주사위 하나를 차례로 던져 표시를 옮깁니다. 큰 그림 칸에 서면 2마르크를 받고, 그림 없는 칸에서는 2마르크 벌금, 41에 닿은 사람이 나머지를 모두 가집니다."],"spots":[["41: 역마차","가운데의 도착점. 손님을 태운 역마차와 마부."],["1: 영국인","출발 칸. 실크해트의 ‘Engländer’."],["기구","하늘에 뜬 기구 칸."],["범선","돛을 활짝 편 배."],["기차","연기를 뿜는 증기 기관차."],["놀이 방법","네 언어로 찍힌 규칙."]]},"huchten":{"title":"목숨을 건 주사위","artist":"얀 판 휘흐턴뷔르흐","date":"1680~1720년","place":"네덜란드","game":"주사위","medium":"캔버스에 유채","size":"67.5×76.0cm","credit":"","p":["전쟁화로 알려진 네덜란드 화가 휘흐턴뷔르흐(1647~1733년)의 작품으로, 왼쪽 아래에 서명이 있습니다. 미술관의 제목은 ‘목숨을 건 주사위 놀이’입니다. 요새 밖에서 죄수 둘이 북 위에 주사위를 던지고, 장교와 병사들이 둘러싸고 있습니다.","오른쪽 뒤에는 교수대가 서 있고, 왼쪽 요새 벽 위에서도 병사들이 보고 있습니다. 죄를 받은 병사 가운데 누가 형을 받을지 주사위로 정하는 장면으로 보입니다. 한 죄수는 북을 가리키고, 다른 죄수는 무릎을 꿇고 눈을 들여다봅니다."],"spots":[["북과 주사위","탁자 대신인 북. 그 위에서 주사위를 던집니다."],["가리키는 죄수","서서 북을 가리키는 죄수."],["무릎 꿇은 죄수","흰 셔츠 차림으로 북에 몸을 숙인 죄수."],["말 탄 장교","모자를 쓰고 말 위에서 내려다보는 장교."],["교수대","오른쪽 위의 교수대."],["벽 위의 병사","요새 벽에서 구경하는 병사들."]]},"vertu":{"title":"덕의 놀이(스펠 데르 되흐트)","artist":"얀 헤리츠 피서르(J. 포르만 고안)","date":"1798년","place":"네덜란드","game":"주사위 2개로 하는 내기 놀이","medium":"인그레이빙, 에칭, 활판","size":"56.9×38.0cm","credit":"","p":["네덜란드어와 프랑스어로 ‘덕의 놀이’라는 제목이 붙은 큰 놀이용 판화입니다. 기둥이 늘어선 신전 가운데에 ‘덕’이 앉아 있고, 왼쪽에 ‘번영’, 오른쪽에 ‘가난’이 서 있습니다. 기둥에는 성실·감사·사랑 같은 덕의 메달이, 아래 받침에는 탐욕·교만·게으름 같은 악덕의 그림이 있습니다.","아래 규칙에 따르면 주사위 2개로도, 제비를 뽑아서도 할 수 있습니다. 주사위로 할 때는 모두 합쳐 63을 걸고, 해가 도는 방향으로 차례로 던집니다. 나온 눈마다 덕이나 악덕이 정해져 있어, 6 쌍인 ‘덕’은 판돈을 모두 가져가고 1 쌍인 ‘악덕’은 8을 냅니다. 그림 아래 ‘T’는 받는 수, ‘B’는 내는 수입니다."],"spots":[["제목","박공의 ‘SPEL DER DEUGD’ 글자."],["덕","가운데 앉은 ‘덕(LA VERTU)’. 6 쌍이면 판돈을 모두 가져갑니다."],["번영","풍요의 뿔을 든 ‘번영’."],["악덕","1 쌍의 ‘악덕(LE VICE)’. 잔을 든 아이의 모습."],["탐욕","받침의 ‘탐욕(L’AVARICE)’. 아래의 ‘B’와 눈은 내는 수입니다."],["놀이 방법","아래에 빽빽이 찍힌 규칙."]]},"charros":{"title":"밀수꾼 차로들(주사위 놀이)","artist":"호세 과달루페 포사다","date":"연대 미상","place":"멕시코","game":"주사위 3개로 하는 경주 놀이","medium":"석판화","size":"29.9×40.4cm","credit":"","p":["‘LOS CHARROS CONTRABANDISTAS(밀수꾼 차로들)／JUEGO DE DADOS(주사위 놀이)’라는 제목의, 포사다가 그림을 그린 말판 놀이입니다. 아래에 ‘A. 바네가스 아로요 인쇄소, 멕시코’라는 출판사 이름이, 오른쪽 아래에 포사다의 서명이 있습니다. 차로는 멕시코의 말 타는 목동으로, 네 귀퉁이에 솜브레로를 쓰고 말을 달리는 모습이 있습니다.","밧줄로 테를 두른 둥근 칸이 판 가득 구불구불 이어지고, 동물과 사람, 기차 등의 그림이 들어 있습니다. 오른쪽 위 ‘설명’에 따르면 주사위는 3개입니다. 처음에 1을 세 개 내면 이기고, 해골 칸에 서면 집니다. 사슴 칸에서는 판돈에서 받고, 도둑 칸에서는 내며, 사자 칸에서는 누가 올 때까지 움직이지 못합니다."],"spots":[["제목","‘LOS CHARROS CONTRABANDISTAS／JUEGO DE DADOS’."],["설명","‘EXPLICACION’으로 시작하는 놀이 방법."],["노는 사람들","왼쪽 아래 탁자에 둘러앉아 판으로 노는 사람들."],["주사위","판 가운데쯤 그려진 주사위 세 개."],["말 탄 차로","올가미를 휘두르며 말을 달리는 차로."],["출판사 이름","‘IMPRENTA DE A. VANEGAS ARROYO, MÉXICO’."]]},"snuffwq":{"title":"바둑 두는 인물을 그린 코담배병","artist":"중국","date":"청대 도광 연간(1820~50년), 도광 관지","place":"중국","game":"바둑","medium":"자기, 상회 채색(분채)","size":"높이 5.7cm","credit":"","p":["청나라 때 가루 담배를 넣어 지니고 다니던 작은 병입니다. 미술관 기록에 따르면 도광 연호의 관지가 있고 1820~50년 작입니다. 높이 6센티미터쯤 되는 흰 자기 몸체에 상회 안료로 산 풍경과 사람들이 그려져 있습니다.","동굴 같은 바위 옆에서 두 노인이 파란 받침 위의 바둑판을 사이에 두고 앉았고, 왼쪽 노인이 돌을 놓으려 합니다. 그 뒤에서 지팡이를 든 아이가 보고 있습니다. 신선의 바둑을 구경한 나무꾼 이야기를 떠올리게 하는 소재로 보입니다."],"spots":[["바둑판","파란 받침 위의 판. 촘촘한 격자가 그려져 있습니다."],["수염 난 노인","보라색 옷을 입고 판에 손을 뻗는 노인."],["맞은편 노인","오른쪽에 앉아 손을 들고 판을 보는 노인."],["지팡이 든 아이","뒤에서 지팡이를 들고 구경하는 아이."],["바위굴","뒤쪽의 동굴 같은 바위."],["마개","초록색 마개."]]},"ostade":{"title":"선술집에서 트릭트랙을 하는 사람들","artist":"아드리안 판 오스타더","date":"1653년","place":"네덜란드(하를럼)","game":"트릭트랙(백개먼의 일종)","medium":"에칭","size":"8.5×7.4cm","credit":"","p":["농민의 생활을 그린 하를럼의 화가 오스타더의 손바닥만 한 에칭입니다. 아래에 ‘A. ostade’라는 서명이 새겨져 있습니다. 어두운 선술집 안, 납 테두리 창으로 든 빛이 사람들을 비춥니다.","왼쪽 탁자에서 두 사람이 트릭트랙 판을 사이에 두고, 뒤에서 한 사람이 들여다봅니다. 오른쪽에서는 남자가 벽에 기대 앉아 잔을 들고 있습니다. 바닥에는 큰 술 단지도 굴러 있어, 한가한 오후의 가게 모습으로 보입니다."],"spots":[["판","탁자 위의 트릭트랙 판."],["왼쪽 사람","모자를 쓰고 판을 마주한 남자."],["오른쪽 사람","판에 몸을 숙인 남자."],["들여다보는 남자","뒤에 서서 승부를 보는 남자."],["쉬는 남자","벽가에 앉아 잔을 든 남자."],["납 테두리 창","마름모 격자 창. 빛이 여기로 들어옵니다."]]},"lenain":{"title":"주사위 놀이를 하는 사람들","artist":"마티외 르냉의 추종자","date":"1630~1680년","place":"프랑스","game":"주사위","medium":"캔버스에 유채","size":"92.8×119.7cm","credit":"","p":["프랑스 르냉 형제 가운데 막내 마티외의 화풍을 따른 화가의 그림입니다. 미술관에 따르면 같은 구도를 가브리엘 드 생토뱅이 그린 스케치가 파리 국립도서관에 있습니다.","야외의 작은 둥근 탁자에 세 남자가 둘러앉아 주사위를 던지고, 두 사람이 곁에서 구경합니다. 왼쪽 남자는 술병을 안고 있습니다. 오른쪽에는 날씬한 사냥개 두 마리가 있고, 트인 곳 너머로 넓은 들판이 보입니다. 탁자 위 작고 흰 것이 주사위입니다."],"spots":[["탁자의 주사위","둥근 탁자 위의 주사위."],["밝은 모자의 남자","앉아서 손을 뻗어 눈을 확인하는 남자."],["검은 옷의 남자","허리에 손을 얹고 선 젊은이."],["뒤의 소년","탁자 뒤에서 승부를 보는 소년."],["병을 든 남자","왼쪽에서 병을 안고 이쪽을 보며 웃는 남자."],["사냥개 두 마리","오른쪽 앞의 날씬한 개들."]]},"tunisie":{"title":"아랍 카페 앞의 카드놀이(안트베르펜 만국박람회 튀니지관)","artist":"작자 미상(인쇄 Ch. 베른회프트)","date":"1894년","place":"벨기에(안트베르펜)","game":"카드놀이","medium":"콜로타이프","size":"15.4×21.6cm","credit":"","p":["1894년 안트베르펜 만국박람회 사진 49장을 묶은 한 벌 중 한 장으로, 위에 ‘EXPOSITION UNIVERSELLE D’ANVERS 1894’, 아래에 ‘튀니지 — 아랍 카페 앞의 카드놀이’라고 찍혀 있습니다. 인쇄는 룩셈부르크의 궁정 사진가 베른회프트가 했습니다.","박람회의 튀니지 구역에 지은, 돔과 탑이 있는 광장에서 찍었습니다. 튀니지 옷차림의 남자들이 타일을 붙인 작은 탁자에 둘러앉아 카드를 하고, 물담배를 피우는 사람과 찻잔 쟁반도 보입니다. 오른쪽에는 양복 차림의 구경꾼이 앉아 있어, 먼 나라의 생활을 보여 주는 전시였던 것으로 보입니다."],"spots":[["카드 탁자","타일 붙인 작은 탁자에서 카드를 든 남자들."],["물담배","왼쪽 남자가 문 물담배 관."],["양복의 구경꾼","오른쪽에 앉은 양복 차림 남자들. 박람회 손님으로 보입니다."],["찻잔 쟁반","탁자 아래의 작은 찻잔."],["돔과 탑","배경에 지은 튀니지풍 건물."],["제목","‘TUNISIE’와 ‘PARTIE DE CARTES DEVANT UN CAFÉ ARABE’."]]},"laghouat":{"title":"라구아트 근교의 카이드들","artist":"작자 미상","date":"1880~1890년","place":"알제리(라구아트 근교)","game":"도미노로 보임","medium":"알부민 프린트","size":"20.9×27.0cm","credit":"","p":["‘알제리 사람들 — 라구아트 근교의 카이드들’이라는 제목의 사진으로, 사진첩에 붙어 있고 ‘239’라는 번호가 찍혀 있습니다. 카이드는 프랑스 통치 아래 알제리에서 지방을 다스린 우두머리를 부르던 말입니다.","흙벽 앞 깔개에 흰 옷의 남자들이 앉아 낮은 탁자 위에 길쭉한 패를 늘어놓고 있습니다. 늘어놓은 모양으로 보아 도미노로 보이지만, 미술관 기록에는 ‘놀이’라고만 되어 있습니다. 앞에는 차 쟁반과 벗어 놓은 신발이 있습니다."],"spots":[["낮은 탁자의 패","탁자 위에 한 줄로 늘어놓은 길쭉한 패."],["차 쟁반","앞 쟁반의 찻잔과 주전자."],["벗어 놓은 신발","깔개 밖에 둔 신발."],["뒤에 선 사람","벽 가에 서서 보는 사람."],["흙벽","뒤쪽의 울퉁불퉁한 흙벽."],["깔개","남자들이 앉은 엮은 깔개."]]},"hangong":{"title":"한궁춘효도(부분)","artist":"구영 그림의 모사","date":"청대(1644~1911년)","place":"중국","game":"바둑(위기)","medium":"두루마리, 비단에 채색","size":"36.2×454.4cm(전체)","credit":"","p":["명나라 화가 구영(1494~1552년)의 구도를 청대에 옮겨 그린, 길이 4.5미터가 넘는 두루마리의 한 부분입니다. 봄날 궁궐에서 궁녀와 소녀, 시녀들이 그네를 타고, 놀이를 하고, 모란을 즐기고, 음악을 연주하고, 금을 타고, 앵무새와 물고기에게 먹이를 주는 모습이 오른쪽에서 왼쪽으로 이어집니다.","이 장면에서는 난간 안쪽에서 두 여인이 바둑판을 사이에 두고 앉았고, 다른 여인들이 몸을 내밀어 들여다봅니다. 앞에는 태호석을 세운 연꽃 모양 화분이 있고, 시녀들이 악기와 보따리를 나릅니다. 미술관 설명처럼 궁궐 깊은 곳에 사는 여인들의 나날을 이상화해 그린 그림입니다."],"spots":[["바둑판","난간 안쪽 탁자 위의 바둑판."],["돌을 놓는 여인","판으로 손을 뻗는 연보라 옷의 여인."],["들여다보는 여인들","몸을 숙여 판을 보는 여인들."],["부채를 든 여인","기둥 사이에서 둥근 부채를 든 여인."],["태호석","연꽃 모양 화분에 세운 푸른 괴석."],["악기를 안은 시녀","비파로 보이는 악기를 안고 걷는 시녀."]]},"homerbg":{"title":"백개먼","artist":"윈슬로 호머","date":"1877년경","place":"미국","game":"백개먼","medium":"목구목판","size":"","credit":"","p":["미국 화가 윈슬로 호머(1836~1910년)의 그림을 새긴 목구목판입니다. 호머는 젊은 시절 잡지 삽화가로서 이런 판화를 위한 그림을 많이 그렸습니다. 아래에 ‘396.—BACKGAMMON.—WINSLOW HOMER.’라고 찍혀 있어, 번호가 붙은 책이나 잡지의 한 장으로 보입니다.","장식이 있는 소파에 두 여인이 마주 앉아, 무릎 위에 걸친 판으로 백개먼을 하고 있습니다. 판 위에 하얗고 둥근 것이 보이지만 무엇인지는 분명하지 않습니다. 긴 치마의 주름과 소파의 소용돌이 팔걸이가 가는 선으로 새겨져 있습니다."],"spots":[["판","두 사람 무릎 위에 걸친 판."],["왼쪽 여인","머리를 틀어 올리고 판에 손을 뻗는 여인."],["오른쪽 여인","몸을 내밀어 판을 보는 여인."],["소파 팔걸이","소용돌이 모양 팔걸이."],["치마","가는 선으로 새긴 긴 치마의 주름."],["제목","아래의 ‘396.—BACKGAMMON.—WINSLOW HOMER.’."]]},"chessst":{"title":"체스를 두는 남녀(입체 사진)","artist":"작자 미상","date":"1852~1858년","place":"미상","game":"체스","medium":"입체 사진(채색)","size":"8.3×16.5cm","credit":"","p":["영어로 ‘The Chess Players(체스 두는 사람들)’라 불리는 두 장 한 쌍의 입체 사진입니다. 입체경으로 보면 판과 말이 앞으로 떠올라 보입니다. 흑백 사진 위에 붉은 커튼과 노란 옷에 색을 입혔습니다.","노란 옷의 여인이 말에 손을 얹고, 맞은편 남자는 등을 보인 채 판을 바라봅니다. 판에는 빨강과 흰색 말이 놓여 대국 중으로 보이지만, 사진관에서 꾸민 장면으로 보입니다. 19세기 중반에는 이런 가정 정경의 입체 사진이 널리 팔렸습니다."],"spots":[["판과 말","격자판 위의 빨강·흰색 말."],["말을 옮기는 손","여인이 말에 손을 얹는 순간."],["여인","흰 깃과 노란 옷의 여인. 고개 숙여 판을 봅니다."],["남자","등을 돌리고 앉은 남자."],["붉은 커튼","배경의 색칠한 커튼."],["다른 한 장","오른쪽 사진. 입체경으로 보면 깊이가 생깁니다."]]},"corrida":{"title":"투우 주사위 놀이(코리다 데 토로스)","artist":"호세 과달루페 포사다","date":"1898년","place":"멕시코","game":"주사위 2개로 하는 판돈 경주 놀이","medium":"사진 제판 볼록판·종이","size":"40.4×30.0cm","credit":"","p":["‘CORRIDA DE TOROS(투우)’라는 제목의, 포사다가 그림을 그린 말판 놀이입니다. 칸은 소용돌이 모양으로 이어지며, 바깥의 1번에서 가운데로 갈수록 투우의 기술과 장면이 차례로 그려져 있습니다. 가운데에는 투우장 건물이, 아래에는 안토니오 바네가스 아로요 인쇄소의 이름이 있습니다.","아래 ‘설명’에 따르면 두 사람 이상이 판돈을 내고 주사위 2개를 던져 나아갑니다. 예컨대 5번 ‘장대높이뛰기’는 10으로 가고, 12번 ‘피카도르가 받히다’는 돈을 내고 쉬며, 28번 ‘가슴 파세’는 처음부터 다시 합니다. 32번 ‘소를 끌어내다’에 닿은 사람이 판돈을 모두 가집니다."],"spots":[["제목","‘CORRIDA DE TOROS’ 글자."],["투우장","소용돌이 한가운데의 투우장 건물."],["1번 칸","소용돌이 입구의 출발 칸."],["소머리","오른쪽 위의 뿔 달린 소머리."],["투우사","왼쪽 아래의 투우사 초상."],["설명","아래쪽의 ‘EXPLICACION’ 글."]]},"ambrocards":{"title":"카드를 하는 세 남자","artist":"작자 미상(미국)","date":"1865년","place":"미국","game":"트럼프","medium":"앰브로타입","size":"14.0×11.0cm","credit":"","p":["앰브로타입은 유리판에 찍은 옅은 음화의 뒷면을 검게 칠해 양화처럼 보이게 한 사진입니다. 다게레오타입보다 싸서 1850~60년대 미국에서 널리 쓰였습니다. 이 한 장은 금색 틀을 대고 붉은 벨벳을 댄 상자에 들어 있습니다.","무늬 없는 배경 앞에서 세 남자가 작은 탁자를 둘러싸고 카드를 쥐고 있습니다. 왼쪽 남자는 중산모, 오른쪽 남자는 캡을 썼고 둘 다 시가를 물었습니다. 가운데 검은 웃옷의 남자는 이쪽을 봅니다. 촬영을 위해 승부 도중인 듯 자세를 잡은 것으로 보입니다."],"spots":[["손패","탁자 위에서 카드를 쥔 손."],["중산모의 남자","왼쪽에서 시가를 문 남자."],["가운데 남자","검은 웃옷으로 이쪽을 보는 남자."],["캡의 남자","오른쪽에서 시가를 문 남자."],["금색 틀","상을 둘러싼 무늬 찍힌 금색 틀."],["상자","붉은 벨벳을 댄 상자."]]},"morphy":{"title":"체스 챔피언 폴 모피","artist":"윈슬로 호머","date":"1859년","place":"미국","game":"체스","medium":"목구목판","size":"","credit":"","p":["아래에 ‘PAUL MORPHY, THE CHESS CHAMPION’이라고 찍힌 초상 목구목판으로, 당시 젊은 삽화가였던 호머(1836~1910년)의 그림을 새긴 것입니다. 모피(1837~1884년)는 뉴올리언스 출신의 체스 명수로, 1858~59년 유럽을 돌며 일류 기사들을 잇달아 꺾고 명성을 얻어 귀국했습니다.","의자에 앉은 젊은 모피가 왼손을 판 가장자리에 얹었고, 곁에는 킹, 룩, 폰 등의 말이 서 있습니다. 그가 귀국해 화제의 인물이 된 1859년의 작품으로, 신문이나 잡지의 삽화로 찍힌 것으로 보입니다."],"spots":[["말","판 위의 킹, 룩, 폰 등."],["판 위의 손","판 가장자리에 얹은 왼손."],["모피의 얼굴","갓 스무 살을 넘긴 젊은 챔피언."],["나비넥타이","단정한 옷차림의 목깃."],["무릎 위의 손","무릎에 얹은 오른손."],["제목","아래의 ‘PAUL MORPHY, THE CHESS CHAMPION’."]]},"dutton":{"title":"셔본 파크 응접실의 더턴 가족","artist":"요한 조파니","date":"1772년경","place":"영국","game":"카드놀이","medium":"캔버스에 유채","size":"101.5×127.0cm","credit":"","p":["독일에서 태어나 영국에서 활약한 조파니(1733~1810년)의 그림입니다. 가족을 편안한 모습으로 그리는 ‘컨버세이션 피스’는 18세기 영국에서 생겨나 인기를 끌었습니다. 무대는 글로스터셔의 저택 셔본 파크의 응접실입니다.","미술관 설명에 따르면 아버지와 딸, 어머니와 아들이 카드놀이에서 다음 수를 궁리하고 있습니다. 가족은 얼마 전 가까운 사람을 잃어, 부모는 정식 상복인 검은 옷을, 자녀들은 가벼운 상복인 연보라·흰색·회색 옷을 입었습니다."],"spots":[["카드 탁자","초록 천을 덮은 탁자와 카드."],["아버지","검은 옷으로 카드를 든 아버지."],["딸","흰 옷으로 카드를 보는 딸."],["아들","회색 옷으로 카드를 든 아들."],["어머니","검은 상복의 어머니."],["벽난로","불이 타는 대리석 벽난로."]]},"whist":{"title":"크리스마스의 학자들——휘스트 연합 게임","artist":"제임스 브레더턴(H. W. 번버리 원화로 보임)","date":"1773년","place":"영국","game":"휘스트(카드)","medium":"에칭","size":"26.5×39.6cm","credit":"","p":["미술관에 따르면 케임브리지 대학 학자들을 풍자한 그림입니다. 왼쪽 아래에 ‘H. W. 번버리 그림 1772’, 오른쪽 아래에 ‘J. 브레더턴 새김’으로 읽히는 글이 있고, 1773년 런던 뉴 본드 가의 가게에서 출판되었습니다. 벽에는 학자의 사각모가 걸려 있습니다.","네 신사가 카드놀이 휘스트를 하며 서로 찡그린 얼굴을 합니다. 휘스트는 둘씩 짝지어 겨루는 놀이라, 제목의 ‘연합 게임’은 말장난으로 보입니다. 뒤에서는 한 사람이 남의 머리 위로 손가락을 세워 놀리고 있습니다. 하인 둘과 개 두 마리도 곁에 있습니다."],"spots":[["탁자의 카드","탁자에 내놓은 카드."],["가발 쓴 학자","큰 가발을 쓰고 패를 가슴에 붙인 학자."],["손가락을 세운 남자","뒤에서 남의 머리 위로 손가락을 세운 남자."],["하녀","모자를 쓰고 쟁반을 든 하인."],["사각모","벽에 걸린 대학 사각모."],["오른쪽 개","오른쪽 아래에서 짖는 작은 개."]]},"hey":{"title":"체스를 두는 세 남자","artist":"파울 하이","date":"1877~1952년","place":"독일","game":"체스","medium":"판화(에칭으로 보임)","size":"19.3×26.0cm","credit":"","p":["독일 화가이자 삽화가 파울 하이(1867~1952년)의 판화입니다. 나이 든 세 남자가 탁자에 다가앉아 하나의 체스판을 들여다봅니다. 가는 선을 겹쳐 깊은 주름과 흰 수염을 그렸습니다.","미술관 기록대로 왼쪽 남자는 턱에 손을 대고, 오른쪽 남자는 손가락에 시가를 끼운 채 말 위로 손을 뻗습니다. 탁자 왼쪽에는 커피잔 두 개, 유리잔과 성냥갑이 있습니다. 카페에서 두는 한 판으로 보입니다."],"spots":[["체스판","탁자 위의 판과 말."],["턱을 괸 남자","흰 수염의 남자. 턱에 손을 대고 생각에 잠깁니다."],["가운데 남자","몸을 내밀어 말에 손을 뻗는 남자."],["오른쪽 남자","뒤에서 들여다보는 남자."],["시가 든 손","손가락에 끼운 시가."],["커피와 성냥갑","왼쪽의 잔 두 개, 유리잔, 성냥갑."]]},"artful":{"title":"교활한 한 장, 할머니에겐 한 장이 너무 많아(하트가 으뜸패!)","artist":"작자 미상","date":"1852~1863년","place":"영국으로 보임","game":"카드놀이","medium":"입체 사진(채색)","size":"8.4×17.4cm","credit":"","p":["영어 제목은 ‘The artful card, or, one too many for granny. Hearts are trumps!’입니다. 교활한 패로 할머니를 이겨 먹는 우스운 장면을 두 장 한 쌍의 입체 사진으로 만든 것입니다. 영어 제목으로 보아 영국에서 만든 것으로 보입니다.","둥근 탁자에서 할머니와 소녀가 카드를 하고, 초록 옷의 아가씨는 패를 든 채 뒤에 선 젊은 남자에게 어깨를 안겨 있습니다. ‘하트가 으뜸패’는 카드의 하트와 연정을 엮은 말장난으로 보입니다. 물레와 찬장이 있는 방은 사진관의 세트일 것입니다."],"spots":[["아가씨의 패","초록 옷 아가씨가 가슴께에 든 카드."],["젊은 남자","뒤에서 아가씨 어깨에 손을 얹은 남자."],["할머니","두건을 쓰고 카드를 내려다보는 노부인."],["소녀","웃으며 카드를 내는 소녀."],["탁자","카드와 소품이 놓인 둥근 탁자."],["찬장","유리문 안에 그릇이 놓인 찬장."]]},"cezcards":{"title":"카드놀이 하는 사람을 위한 습작","artist":"폴 세잔","date":"1890~92년","place":"프랑스","game":"트럼프","medium":"수채, 연필·베이지색 종이","size":"36.2×48.5cm","credit":"","p":["세잔은 1890년대 남프랑스 엑스에서 카드놀이 하는 남자들을 여러 점 그렸습니다. 이것은 그 연작을 위한 수채 습작으로, 모자를 쓰고 콧수염을 기른 남자가 탁자 앞에서 손패를 보고 있습니다.","연필 선 위에 파랑과 회색 수채를 엷게 겹쳐 웃옷의 주름과 몸의 덩어리를 잡았습니다. 오른쪽과 탁자 끝은 그리다 만 채 남겨 두고, 인물 둘레에만 색을 올렸습니다. 모델은 그 지방에서 일하던 사람들이었다고 합니다."],"spots":[["남자의 얼굴","모자 아래 눈을 내리깔고 패를 보는 남자."],["손패","두 손에 쥔 카드."],["탁자","연필 선으로만 그린 탁자."],["의자","왼쪽의 의자 등받이."],["웃옷","파랑과 회색을 겹친 주름."],["미완성 부분","탁자 다리 쪽은 선만 남아 있습니다."]]},"vuillardck":{"title":"다마 승부(『풍경과 실내』 중에서)","artist":"에두아르 뷔야르","date":"1899년","place":"프랑스","game":"다마(체커)","medium":"다색 석판화·회색빛 상아색 종이","size":"36.9×28.5cm","credit":"","p":["프랑스 화가 뷔야르가 화상 앙브루아즈 볼라르의 출판으로 만든 다색 석판화집 『풍경과 실내』의 첫 장입니다. 인쇄는 석판 인쇄공 오귀스트 클로가 맡았습니다.","무늬투성이 벽지의 방에서 수염 난 남자가 다마 판에 앉아 있고, 격자무늬 옷의 여인이 서서 턱에 손을 대고 판을 들여다봅니다. 사람도 벽지도 소파도 평평한 색과 무늬에 녹아들고, 판의 흑백 바둑판무늬만 또렷하게 떠오릅니다."],"spots":[["판","흑백 체크무늬의 다마 판."],["수염 난 남자","판 앞에 앉은 남자."],["서 있는 여인","격자무늬 옷으로 턱에 손을 댄 여인."],["벽지","구불구불한 선으로 가득한 벽지."],["꽃무늬 쿠션","왼쪽 아래의 꽃무늬 천."],["램프","벽 곁의 가느다란 램프 같은 형태."]]},"cruikchess":{"title":"체스 승부","artist":"조지 크룩섕크(프레더릭 매리엇 대위의 밑그림에 따름)","date":"1814년","place":"영국","game":"체스","medium":"손으로 채색한 에칭","size":"23.8×34.5cm","credit":"","p":["영국의 풍자 화가 크룩섕크가, 해군 장교이자 뒤에 소설가가 된 매리엇의 밑그림을 판화로 만든 것으로, 런던의 해나 험프리가 펴냈습니다. 아래에 ‘GAME of CHESS’라는 제목이 있습니다.","촛불이 선 탁자에서 두 노신사가 체스판에 마주 앉았습니다. 각자 뒤에는 구경꾼이 서 있는데, 왼쪽 남자는 입에 손가락을 대며 ‘조용히’ 하고, 오른쪽 남자는 손잡이 달린 안경으로 판을 들여다봅니다. 훈수 두고 싶어 하는 구경꾼을 놀리는 그림으로 보입니다."],"spots":[["판","흑백 말이 늘어선 체스판."],["촛불","판을 비추는 촛불 두 자루."],["‘쉿’ 하는 남자","입에 손가락을 댄 구경꾼."],["안경 든 남자","손잡이 안경으로 판을 보는 구경꾼."],["잠든 개","탁자 밑에서 자는 개."],["제목","아래의 ‘GAME of CHESS’."]]},"domino98":{"title":"탁자에서 도미노를 하는 여인과 아이","artist":"작자 미상(미국)","date":"1898년경","place":"미국","game":"도미노","medium":"알부민 프린트(유리에 부착)","size":"40.8×51.1cm","credit":"","p":["미국 사진관에서 찍은 것으로 보이는 큰 사진으로, 유리판에 붙여 마감했습니다. 흰 옷의 여인과 곱슬머리 여자아이가 꽃을 꽂은 작은 탁자를 사이에 두고 앉아 있습니다.","탁자 위에는 도미노 패가 놓여 있고, 여인은 패를 하나 내려놓는 중입니다. 아이는 턱을 괴고 그것을 바라봅니다. 커튼, 장식장, 그림이 걸린 벽은 사진관 배경으로 보입니다."],"spots":[["도미노 패","탁자에 놓인 흰 도미노."],["여자아이","턱을 괴고 패를 보는 아이."],["여인","흰 옷을 입고 패를 내려놓는 여인."],["꽃","탁자 위 꽃병의 꽃."],["장식장","오른쪽 뒤의 화려한 장식장."],["글씨","오른쪽 아래의 흰 글자."]]},"langkat":{"title":"배 위에서 카드를 하는 알베르트 글라저와 친구들(수마트라, 랑캇)","artist":"작자 미상(H. 에른스트 사)","date":"1895~1905년","place":"인도네시아(수마트라섬, 랑캇)","game":"카드놀이","medium":"사진","size":"17.5×22.8cm","credit":"","p":["수마트라섬 북부 랑캇에서 찍은 사진입니다. 오른쪽 아래에 사진관 ‘H. Ernst & Co. / Bindjey Langkat’의 압인이 있고, 뒷면에는 가운데 인물이 알베르트 글라저이며 어느 부인의 형제라고 손글씨로 적혀 있습니다.","차양을 친 배의 갑판에서 흰 옷의 세 남자가 탁자에 둘러앉아 카드를 들고 있습니다. 탁자 위에는 패와 동전 같은 작은 것들이 있고, 오른쪽 남자 곁에는 병이 있습니다. 흰 옷과 차양이 더운 고장의 생활을 전해 줍니다."],"spots":[["탁자 위","나누어 준 패와 동전 같은 것들."],["글라저","가운데에서 패를 펼친 인물. 뒷면에 이름이 있습니다."],["왼쪽 남자","등을 반쯤 보이며 패를 든 남자."],["오른쪽 남자","콧수염의 남자. 패를 들고 탁자에 앉아 있습니다."],["병","오른쪽 남자 곁의 병."],["차양","지붕에서 늘어진 잎 장식과 차양."]]},"chatur":{"title":"차투랑가 한 판","artist":"작자 미상","date":"1805~1815년","place":"인도","game":"차투랑가","medium":"구아슈·금, 붓","size":"16.2×9.8cm(화면)","credit":"","p":["인도의 세밀화입니다. 미술관 기록에 따르면 두 여인이 차투랑가라는 판 놀이를 하고, 시녀가 파리채를 들고 있습니다. 차투랑가는 인도의 오래된 판 놀이로 체스의 조상으로 여겨집니다.","흰 기둥의 아치 아래 붉은 깔개 위에서, 남색 옷의 여인과 주황 옷의 여인이 체크무늬 판을 사이에 두고 마주 앉아 있습니다. 주황 옷의 여인은 손을 내밀어 무언가 말하는 듯합니다. 그림 둘레는 검고 흰 선으로 테를 두른 짙은 빨강 틀로 싸여 있습니다."],"spots":[["판","붉은 깔개 위의 체크무늬 판."],["남색 옷의 여인","금 장신구를 하고 판에 손을 뻗는 여인."],["주황 옷의 여인","손을 내밀며 마주한 여인."],["시녀","뒤에 서 있는 시녀."],["파리채","시녀가 든 파리채."],["붉은 틀","검고 흰 선으로 테를 두른 짙은 빨강 틀."]]},"shabbarat":{"title":"여인들의 처소의 밤","artist":"작자 미상","date":"1760~1770년","place":"인도","game":"차우파르(파치시)","medium":"구아슈·금, 붓","size":"34.3×25.6cm","credit":"","p":["인도의 세밀화입니다. 미술관 기록에 따르면 궁전의 넓은 안뜰에서 네 여인이 판 놀이를 하고 있으며, 그 놀이는 차우파르 또는 파치시라고 합니다. 여인들이 십자형 천 판을 둘러싸고 앉아 있습니다.","앞쪽 오른쪽 여인은 긴 막대 모양 주사위 세 개를 들고 막 던지려 합니다. 그 옆에서 베개에 기댄 이가 가장 신분이 높은 여인입니다. 밤이지만 테라스 곳곳에 등불이 놓였고, 먼 도시 성벽에도 수많은 불빛이 켜져 있습니다. 기록은 이슬람 축제 샤베 바라트를 기리는 모습일 것이라고 합니다."],"spots":[["십자형 판","바닥에 펼친 십자형 판."],["주사위를 든 여인","막대 주사위를 든 앞쪽 여인."],["베개에 기댄 여인","가장 신분이 높은 여인."],["시녀","쟁반을 들고 다가오는 여인."],["등불","유리 덮개 안에서 타는 초."],["먼 정자","분수가 있는 정원과 정자, 도시의 불빛."]]},"govase":{"title":"바둑 두는 여인들을 그린 달걀형 화병","artist":"작자 미상(‘당금당’ 인장)","date":"1724년","place":"중국(광둥)","game":"바둑","medium":"자기, 상회(분채)·금채","size":"높이 15.3cm","credit":"","p":["아주 얇은 자기에 채색으로 그린 중국 화병입니다. 뒷면에는 ‘갑진년 화조일(꽃 축제 날)에 영남 주강 가의 아늑한 집에서 그린 바둑 한 판의 그림’이라는 글과 ‘당금당’의 붉은 인장이 있습니다. 헤이그의 수집가 루아예의 자기 컬렉션 가운데 한 점입니다.","두 여인이 탁자 위 바둑판을 사이에 두고, 왼쪽 여인은 바둑돌 그릇을 들고 있습니다. 오른쪽에서는 여인 둘과 아이 둘이 승부를 들여다봅니다. 뒤쪽 받침대에는 공작 깃털을 꽂은 화병과 산호 같은 골동품이 놓여 있습니다."],"spots":[["바둑판","탁자 위의 바둑판과 흑백 돌."],["왼쪽 기사","돌 그릇을 들고 손가락을 가리키는 여인."],["오른쪽 기사","판으로 몸을 내민 여인."],["구경하는 여인들","뒤에서 판을 들여다보는 여인들."],["공작 깃털과 산호","받침대 화병에 꽂은 공작 깃털과 산호."],["바둑돌 그릇","왼쪽 여인이 든 돌 그릇."]]},"yokihi":{"title":"현종과 양귀비의 쌍륙","artist":"작자 미상(스리모노)","date":"1822년","place":"일본","game":"반스고로쿠(쌍륙)","medium":"다색 목판화, 금속 안료","size":"21.6×19.1cm","credit":"","p":["스리모노는 그림에 교카 같은 시를 곁들여 두꺼운 종이와 금속 가루로 호화롭게 찍은 판화로, 시인들이 동료에게 줄 선물로 주문했습니다. 이 한 장에는 교카 한 수와 시인의 이름 ‘다치바나노 고엔’이 찍혀 있습니다.","미술관 기록에 따르면 당나라 현종(685~762년)이 총애하던 양귀비(719~756년)와 스고로쿠를 두는 장면으로, 이 놀이는 백개먼·트릭트랙과 같은 계열입니다. 붉은 받침 위 상자 모양 판에 흑백 말이 놓여 있습니다."],"spots":[["판","붉은 받침 위의 상자 모양 쌍륙판과 말."],["양귀비","머리에 꽃 장식을 하고 판에 손을 얹은 양귀비."],["현종","턱에 손을 대고 판을 보는 현종."],["교카","왼쪽 위의 시 한 수와 시인 이름."],["병풍","뒤쪽 산을 그린 병풍."],["서명과 인장","오른쪽 아래의 서명과 붉은 인장."]]},"disderi":{"title":"뱃사람 복장으로 카드를 하는 남자들","artist":"디스데리 사","date":"1850~1890년","place":"프랑스(파리)","game":"카드놀이","medium":"알부민 프린트(명함판 사진)","size":"8.6×5.3cm","credit":"","p":["사진첩에 붙어 있던 명함판 사진으로, 뒷면에 파리 ‘디스데리 사(이탈리앵 대로 8번지)’가 찍혀 있습니다. 디스데리는 명함처럼 작은 사진을 한 번에 여러 장 찍어 내는 ‘카르트 드 비지트’를 널리 퍼뜨린 사진가입니다.","삼각모에 긴 웃옷, 흰 양말의 옛날식 차림을 한 남자들이 무늬 있는 탁자에 둘러앉아 카드를 하고 있습니다. 미술관 기록은 ‘뱃사람 복장’이라 하지만, 연극이나 가장을 위한 의상으로 보입니다. 가운데 남자는 일어서서 탁자를 들여다봅니다."],"spots":[["탁자","무늬 테두리가 있는 탁자. 패와 잔이 보입니다."],["일어선 남자","삼각모를 쓰고 탁자를 들여다보는 남자."],["왼쪽 남자","패를 들고 앉은 남자."],["오른쪽 남자","삼각모를 쓰고 패를 든 남자."],["버클 구두","흰 양말과 버클 달린 구두."],["금색 틀","사진을 두른 대지의 금색 틀."]]},"gans":{"title":"거위 판(74칸 소용돌이)","artist":"얀 오르트만(아버지), 다니엘 빌럼 스토펜달 도안","date":"1763~1823년","place":"네덜란드","game":"거위 놀이(주사위 경주)","medium":"목판(파랑·빨강·초록 채색)","size":"40.8×46.8cm","credit":"","p":["네덜란드에서 찍은 소용돌이 모양의 경주 판입니다. 미술관에 따르면 칸은 1부터 74까지이고, 몇몇 칸에 그림이 있습니다. 판은 얀 오르트만이 새겼고, 도안자 스토펜달의 이름이 ‘invenit(고안)’과 함께 오른쪽 아래에 있습니다.","도착점 74는 가운데, 해 지는 바닷가에 선 신전입니다. 칸에는 ‘LEER GELD(수업료)’, ‘DWAALWEG(헤매는 길)’, ‘DOMHEID / WYSHEID(어리석음/지혜)’ 같은 말과, 큰 낫을 든 해골의 ‘EINDE(끝)’가 있어 인생의 길을 가르치는 교훈 놀이로 보입니다."],"spots":[["74: 신전","도착점 신전. 해 지는 바닷가에 서 있습니다."],["1: 출발","왼쪽 아래 첫 칸."],["수업료","‘LEER GELD’ 칸. 여기 서면 돈을 내는 것으로 보입니다."],["헤매는 길","‘DWAALWEG’라고 적힌 숲길."],["끝","큰 낫을 든 해골 ‘EINDE’."],["주사위","주사위 두 개가 그려진 칸."]]},"merelle":{"title":"메렐과 연날리기","artist":"클로딘 스텔라(자크 스텔라 원화)","date":"1657년","place":"프랑스(파리)","game":"메렐(나인 멘스 모리스)","medium":"인그레이빙","size":"11.7×14.1cm","credit":"","p":["화가 자크 스텔라의 도안을 조카 클로딘이 새긴 아이들 놀이 연작의 17번입니다. 미술관에 따르면 판화 51장을 묶은 앨범의 한 장입니다. 노는 것은 통통한 벌거숭이 아이들(푸토)입니다.","왼쪽 앞에서는 돌 받침에 새긴 판에서 ‘메렐(나인 멘스 모리스)’을 합니다. 오른쪽 땅에는 네모 칸에 동전을 던지는 ‘프랑 뒤 카로’의 선이 그어져 있고, 멀리서는 한 아이가 연을 날리며 달립니다. 아래 시는 어느 놀이든 모두 열심이라고 노래합니다."],"spots":[["메렐 판","돌 받침에 새긴 판과 놓인 말."],["연","하늘 높이 뜬 연."],["연 날리는 아이","실을 잡고 달리는 아이."],["프랑 뒤 카로","땅에 그은 네모와 대각선."],["가리키는 아이","무언가를 들고 땅의 선을 가리키는 아이."],["제목","‘LA MERELLE, & LE CERF VOLANT’ 글자."]]},"feldcards":{"title":"뜰의 탁자에서 카드를 하는 사람들(입체 사진)","artist":"작자 미상","date":"1850~1880년","place":"미상(뒷면에 흐로닝언 가게 도장)","game":"카드놀이","medium":"알부민 프린트(입체 사진)","size":"8.5×17.0cm","credit":"","p":["담쟁이가 격자 울타리를 덮은 뜰에서 가족인지 친구들인지 모를 사람들이 탁자에 둘러앉아 카드를 하는 입체 사진입니다. 뒷면에 네덜란드 흐로닝언의 ‘펠트브뤼허 사’ 도장이 찍혀 있는데, 판매한 가게나 출판사의 도장으로 보입니다.","왼쪽의 수염 난 남자가 패를 높이 쳐들어 막 탁자에 내리치려 합니다. 턱을 괸 남자, 패를 든 소년, 백발의 노인, 뒤에서 지켜보는 여인이 승부의 한순간을 이룹니다. 오래 움직이지 않아야 했으니 자세를 잡은 장면으로 보입니다."],"spots":[["쳐든 패","수염 난 남자가 높이 든 한 장."],["탁자 위","이미 낸 패."],["소년의 패","등을 보인 소년이 든 패."],["백발 노인","오른쪽에 앉은 노인."],["지켜보는 여인","뒤에 서서 승부를 보는 여인."],["수놓은 의자","앞쪽의 꽃무늬 천을 씌운 의자."]]},"tempel":{"title":"말판 ‘행운의 신전’","artist":"작자 미상","date":"1816년","place":"네덜란드","game":"주사위로 하는 경주 놀이","medium":"목판, 활판 글자","size":"43.0×48.5cm","credit":"","p":["1부터 74까지의 칸이 소용돌이로 이어지는 놀이용 낱장입니다. 가운데에는 바닷가의 둥근 신전이 그려져 있으며, 같은 소장품에 남은 놀이 규칙 종이는 이를 ‘행운의 신전’이라 부르고 ‘던지는 놀이’, 곧 주사위 놀이라고 적었습니다.","칸은 대부분 빈 동그라미지만, 군데군데 장미, 가시, 주사위, 쇠문, 나룻배 등의 그림과 ‘LEER GELD(수업료)’, ‘DOMHEID(어리석음)’, ‘WYSHEID(지혜)’ 같은 글자가 들어 있습니다. 선행과 악행을 지나 신전으로 향하는 교훈적인 말판 놀이로 보입니다."],"spots":[["행운의 신전","가운데 바닷가의 신전. 74번 도착점입니다."],["1번 칸","왼쪽 아래에서 시작하는 출발 칸."],["수업료","‘LEER GELD’라고 적힌 칸."],["주사위","윗줄에 그려진 주사위 두 개."],["나룻배","아랫줄의 ‘OVER HAAL(나루)’ 그림."],["어리석음과 지혜","오른쪽의 ‘DOMHEID’ ‘WYSHEID’."]]},"verkeer":{"title":"작은 판(페르케이르 판)","artist":"작자 미상","date":"1690~1710년","place":"네덜란드(암스테르담)","game":"페르케이르(백개먼의 일종), 체스, 나인 멘스 모리스","medium":"호두나무, 올리브나무·흑단·회양목·뼈 상감, 구리 장식","size":"접어서 5.8×5.8cm(펴서 11.6cm)","credit":"","p":["한 변이 겨우 6센티미터쯤인, 상자처럼 열리는 놀이판입니다. 바깥에는 체스판과 나인 멘스 모리스 판이, 안쪽에는 페르케이르(네덜란드의 백개먼 일종) 판이 있으며 구리 경첩과 작은 고리로 닫습니다.","안에는 주사위 1개, 뼈 말 9개, 흑단 말 4개, 작은 동전 3개가 남아 있습니다. 미술관 번호로 보아 페트로넬라 오르트만의 인형의 집 세간 가운데 하나로 보입니다. 작아도 나무 상감은 정성스럽고 진짜 판과 같은 짜임입니다."],"spots":[["주사위","쌀알만 한 주사위."],["뼈 말","하얀 뼈로 된 둥근 말."],["흑단 말","검은 흑단 말."],["삼각형 칸","밝은 나무와 어두운 나무를 번갈아 상감한 삼각형."],["경첩","반으로 접는 구리 경첩."],["고리","닫는 데 쓰는 작은 구리 고리."]]},"silverbd":{"title":"은으로 만든 작은 판과 말","artist":"프레데릭 판 스트란트 2세","date":"1739년","place":"네덜란드(암스테르담)","game":"다마(체커), 나인 멘스 모리스","medium":"은","size":"5.4×5.4cm","credit":"","p":["가로세로 5.4센티미터의 은판으로, 64칸 판에 테두리를 세우고 걸기 위한 고리를 달았습니다. 어두운 칸에는 가는 선이 새겨져 있고, 뒷면에는 나인 멘스 모리스의 선이 새겨져 있습니다.","암스테르담 도시 각인, 1739년을 뜻하는 연도 기호 ‘E’, 은세공사 프레데릭 판 스트란트 2세의 각인이 찍혀 있습니다. 다마 말 15개가 함께 남아 있는데, 8개에는 꽃, 7개에는 원 무늬가 있습니다. 인형의 집이나 장식장에 두던 은 미니어처로 보입니다."],"spots":[["꽃무늬 말","꽃무늬를 찍은 말."],["원무늬 말","원 무늬의 말."],["고리","판 모서리의 고리."],["새긴 칸","가는 선을 새긴 어두운 칸."],["매끈한 칸","그대로 닦은 밝은 칸."],["테두리","판 둘레에 선 테두리."]]},"schaak1550":{"title":"말 탄 말들의 체스 세트","artist":"작자 미상","date":"1550년","place":"독일","game":"체스","medium":"회양목, 침엽수재","size":"가장 큰 말 높이 10.5cm","credit":"","p":["말마다 돌려 깎은 받침에 꽃무늬 난간을 두르고, 그 위에 사람과 말을 새겼습니다. 왕과 여왕은 말이나 노새를 타고 사냥에 나서는 모습입니다.","미술관 기록에 따르면 흑의 왕은 용을 밟고 뒷발로 선 말을 타고, 목에는 금양모 기사단을 떠올리게 하는 사슬을 걸어 카를 5세가 아닐까 합니다. 여왕은 손에 매를 얹고 노새에 옆으로 앉았습니다. 오른쪽 끝에는 원숭이가 사람 등에 탄 익살스러운 말도 있습니다."],"spots":[["왕","관을 쓰고 수염을 기른 말 위의 왕."],["여왕","매를 들고 노새에 옆으로 앉은 여왕."],["원숭이 말","사람 등에 탄 원숭이."],["익살스러운 말","맨 왼쪽, 사람이 사람 등에 탄 말."],["발밑의 생물","말발굽 아래 웅크린 용과 짐승."],["받침","꽃무늬 난간을 두른 받침."]]},"kraaij":{"title":"거실에서 판 놀이를 하는 남녀","artist":"작자 미상","date":"1900~1910년","place":"네덜란드로 보임","game":"백개먼","medium":"일광 현상 콜로디온 은염 프린트","size":"8.0×11.1cm","credit":"","p":["포도주 상인 ‘크라이 사(보르도·암스테르담)’의 사진 등이 든 어느 가족 사진첩의 한 장입니다. 샹들리에가 달린 거실에서 가족이나 지인으로 보이는 남녀가 탁자에 둘러앉아 있습니다.","탁자 위에는 접이식 상자형 판이 펼쳐져 있고, 좌우의 여인이 각각 주사위 통을 들고 있습니다. 미술관 기록은 ‘판 놀이’지만 상자형 판과 통으로 보아 백개먼으로 보입니다. 곁에는 커피잔, 안쪽에는 새장이 보여 편안한 집의 저녁 분위기가 전해집니다."],"spots":[["상자형 판","접이식 상자를 펼친 판."],["왼쪽 주사위 통","안경 쓴 여인이 든 통."],["오른쪽 주사위 통","물방울무늬 옷의 여인이 흔들려는 통."],["새장","안쪽 받침대 위의 새장."],["샹들리에","천장에서 늘어진 유리 갓 등."],["서 있는 남자","오른쪽에 서서 승부를 내려다보는 남자."]]},"braekel":{"title":"다마를 두는 노부부","artist":"페르디난트 더 브라컬레이르(아버지)","date":"1862년","place":"벨기에(안트베르펜)","game":"다마(체커)","medium":"에칭","size":"21.8×16.5cm","credit":"","p":["안트베르펜의 화가 더 브라컬레이르(1792~1883년)의 에칭으로, 왼쪽 아래에 ‘Ferdinand De Braekeleer Antwerpen 1862’라는 서명이 있습니다. 난로가 있는 오래된 부엌에서 노인과 노파가 작은 탁자를 사이에 두고 앉았습니다.","탁자 위 판에 둥근 말이 놓여 있고, 노인은 말을 집고 노파는 손을 펴서 대꾸하는 듯합니다. 바닥에는 모자가 놓여 있고 말도 몇 개 떨어져 있습니다. 선반에는 접시가 늘어서 있고, 창밖으로 집들이 보입니다."],"spots":[["판과 말","탁자 위의 판과 둥근 말."],["노인","몸을 숙여 말을 집는 남자."],["노파","두건을 쓰고 손을 펴며 말하는 여자."],["바닥의 모자","바닥에 놓인 노인의 모자."],["서명","‘Ferdinand De Braekeleer Antwerpen 1862’."],["선반의 접시","난로 위 선반의 큰 접시."]]},"billiard":{"title":"당구","artist":"H. W. 번버리 원화에 따름(새긴 이 미상)","date":"1780년","place":"영국(런던)","game":"당구","medium":"에칭과 점각","size":"30.0×39.1cm","credit":"","p":["영국의 풍자화가 헨리 윌리엄 번버리의 원화를 바탕으로 한 판화로, 1780년 런던의 왓슨 & 디킨슨 가게에서 출판되었습니다. 미술관에 따르면 연작의 네 번째입니다.","두 남자가 당구를 치고, 주위 사람들이 숨을 죽이고 지켜봅니다. 한 사람은 대 위로 몸을 내밀어 큐를 겨누고, 다른 사람은 큐를 어깨에 메고 있습니다. 벽에는 큐 걸이와 점수를 세는 둥근 판 두 개가 있습니다. 미술관은 당구대가 삼각형처럼 보인다고 적고 있습니다."],"spots":[["당구대와 공","천을 씌운 대와 그 위의 공."],["겨누는 남자","대 위로 몸을 내밀어 큐를 내미는 남자."],["큐를 멘 남자","긴 큐를 들고 기다리는 남자."],["점수판","벽의 둥근 판 두 개. 점수를 세는 도구로 보입니다."],["큐 걸이","벽에 세운 큐들."],["웃는 두 사람","오른쪽에서 얼굴을 맞대고 웃는 구경꾼."]]},"baizi":{"title":"백자도(부분)","artist":"쉬양훙","date":"18세기","place":"중국","game":"바둑","medium":"두루마리, 종이에 수묵(담채)","size":"29.8×526cm(전체)","credit":"","p":["중국의 직업 화가 쉬양훙이 그린, 길이 5미터가 넘는 두루마리에서 바둑 장면을 잘라 냈습니다. 정원에서 백 명의 아이들이 놀고, 음악을 연주하고, 책을 읽고, 글씨를 씁니다. ‘백자’는 아시아 미술의 중요한 주제로, 자손이 많고 집안이 번성함을 뜻합니다.","이 두루마리는 뒤에 일본의 다니 분초가 베껴 그린 것으로도 알려져 있으며, 모사본도 같은 미술관에 있습니다. 파초와 태호석 곁에서 아이들이 낮은 받침의 바둑판을 둘러싸고, 둘이 돌 그릇을 들고 두며 다른 아이들이 들여다봅니다."],"spots":[["바둑판","낮은 받침 위의 바둑판과 돌."],["돌을 놓는 아이","파란 웃옷으로 돌 그릇에 손을 넣은 아이."],["또 한 명의 기사","판으로 몸을 내민 흰 옷의 아이."],["머리에 손을 얹은 아이","뒤에서 머리를 감싸고 보는 아이."],["태호석","구멍이 숭숭한 큰 괴석."],["깃털 부채","왼쪽에서 깃털 부채를 든 아이."]]},"schenkcards":{"title":"카드놀이를 하는 두 중국 여인","artist":"피터르 스헹크(아들)","date":"1727~1775년","place":"네덜란드(주제는 중국)","game":"카드놀이","medium":"에칭","size":"16.5×26.2cm","credit":"","p":["암스테르담의 출판업자이자 판화가 피터르 스헹크(아들)가 펴낸 중국풍 인물·풍경 판화집 『새로 고안한 중국인들』 제1부의 한 장입니다. 유럽에서 유행한 ‘시누아즈리(중국 취미)’ 판화로, 상상 속의 중국을 그렸습니다.","미술관 기록에 따르면 정원에서 두 중국 여인이 카드놀이를 하고, 오른쪽에서 음식을 담은 쟁반을 든 여인이 옵니다. 탁자 위의 패는 유럽의 트럼프처럼 보입니다. 왼쪽 받침대 위에서는 토끼가 쉬고, 강에는 돛단배가 떠 있습니다."],"spots":[["탁자의 패","탁자에 펼친 카드. 유럽 카드처럼 보입니다."],["왼쪽 여인","패를 들고 상대를 보는 여인."],["오른쪽 여인","패를 탁자에 놓는 여인."],["쟁반을 든 여인","음식을 담은 쟁반을 나르는 여인."],["토끼","왼쪽 받침대 위에서 쉬는 토끼."],["돛단배","강에 떠 있는 돛단배."]]},"gosaucer":{"title":"바둑 두는 사람들을 그린 접시","artist":"작자 미상","date":"1725~1735년","place":"중국","game":"바둑","medium":"자기, 상회(분채)·금채","size":"지름 16.4cm","credit":"","p":["분채라 불리는 부드러운 상회 채색으로 그린 중국 접시입니다. 밑면에는 붓·여의·먹을 이중 원으로 두른 표시가 있습니다. 미술관 기록에는 ‘남녀가 바둑을 둔다’고도, ‘세 여인 중 둘이 바둑을 둔다’고도 되어 있어 인물에 대한 해석이 엇갈립니다.","방 안 탁자에 바둑판이 놓여 두 사람이 마주 보며 돌을 놓고, 다른 한 사람이 뒤에 서서 봅니다. 탁자에는 노란 돌 그릇, 뒤에는 꽃을 꽂은 화병을 올린 받침대, 오른쪽에는 큰 파란 항아리가 있습니다."],"spots":[["바둑판","탁자 위의 바둑판과 돌."],["왼쪽 기사","연보라 옷으로 탁자에 기댄 사람."],["오른쪽 기사","분홍 옷으로 돌을 놓는 사람."],["구경꾼","뒤에 서서 보는 사람."],["화병","받침대 위의 꽃병."],["파란 항아리","오른쪽의 큰 항아리."]]},"cheetham":{"title":"작은 카드 모임(러시아에서)","artist":"작자 미상","date":"1903~1904년","place":"러시아","game":"카드놀이","medium":"일광 현상 젤라틴 은염 프린트","size":"9.2×11.5cm","credit":"","p":["러시아에 살던 영국 치섬 가족의 사진첩에 있는 사진으로, 대지에 영어로 ‘a little card-party(작은 카드 모임)’라고 적혀 있습니다. 미술관은 사진 속 사람들이 조지프 치섬을 찾아온 영국 친구들일 것이라고 적고 있습니다.","벽지를 바른 방에서 세 사람이 꽃무늬 식탁보를 덮은 탁자에 둘러앉아 패를 펼치고 있습니다. 촛대 두 개가 서 있고, 가운데 여인은 패를 부채처럼 펼치며 웃고 있습니다. 먼 타국에서 고향 친구들과 보내는 편안한 한때로 보입니다."],"spots":[["왼쪽 남자의 패","수염 난 남자가 펼친 패."],["여인의 패","가운데 여인이 부채처럼 편 패."],["오른쪽 남자","몸을 내밀어 패를 든 남자."],["촛대","탁자 위의 촛대 두 개."],["식탁보","꽃과 무늬가 있는 큰 식탁보."],["글씨","대지의 ‘a little card-party’."]]},"problem":{"title":"난제(체스를 두는 남녀·입체 사진)","artist":"작자 미상","date":"1852~1863년","place":"미상","game":"체스","medium":"입체 사진(채색)","size":"8.4×17.4cm","credit":"","p":["영어 제목은 ‘The Problem(난제)’입니다. 흰 가발에 18세기풍 옷을 입은 두 사람이 장식 다리 탁자에서 체스를 두는 장면을, 색을 입힌 두 장 한 쌍의 입체 사진으로 만들었습니다. 뒷면에는 ‘Simons’라고 손글씨가 있습니다.","젊은 쪽은 두 손으로 볼을 감싸고 판을 노려보고, 맞은편 나이 든 남자는 씩 웃고 있습니다. 누가 난제를 안고 있는지 한눈에 알 수 있는 연극 같은 장면으로 보입니다. 발치에는 개가 엎드려 있습니다."],"spots":[["판과 말","장식 다리 탁자 위의 판과 말."],["고민하는 사람","두 손으로 볼을 감싸고 판을 보는 사람."],["웃는 남자","파란 웃옷을 입고 씩 웃는 나이 든 남자."],["개","발치에 엎드린 개."],["붉은 커튼","색칠한 배경 커튼."],["다른 한 장","오른쪽 사진. 입체경으로 보면 깊이가 생깁니다."]]},"tarocco":{"title":"타로 카드 열 장","artist":"작자 미상(주세페 마리아 미텔리의 도안으로 보임)","date":"1660~1718년","place":"이탈리아(볼로냐)","game":"타로키(타로 카드놀이)","medium":"에칭과 인그레이빙, 일부 연갈색 수채색","size":"대지에 붙인 열 장","credit":"","p":["볼로냐에서 만든 타로 한 벌에서 열 장을 골라 대지에 나란히 붙인 것입니다. 타로는 원래 점이 아니라 으뜸패가 있는 카드놀이에 쓰였습니다. 윗줄 왼쪽 끝은 표제 카드로, 미술관은 그 초상이 화가 미텔리일지도 모른다고 봅니다.","윗줄에는 관을 쓴 사람, 말 탄 사람 등 네 인물이, 아랫줄에는 ‘금화’ 무늬의 6부터 10까지가 있고 수만큼 금화가 찍혀 있습니다. 판화로 찍은 선 위에 일부 연한 갈색을 칠했습니다."],"spots":[["표제 카드","왼쪽 위, 초상 액자와 글귀가 든 카드."],["관 쓴 남자","홀을 든, 관을 쓴 인물."],["서 있는 여인","관을 쓰고 잔을 든 여인."],["말 탄 사람","말을 탄 인물의 카드."],["금화 10","아랫줄 왼쪽, 금화 열 개."],["금화 6","아랫줄 오른쪽, 금화 여섯 개."]]},"kindtegel":{"title":"아이들의 놀이 타일","artist":"작자 미상","date":"1680~1730년","place":"네덜란드","game":"아이들 놀이(죽마, 그네 등)","medium":"주석유 도기(델프트 타일), 파란 채색","size":"107×80cm(48장)","credit":"","p":["세로 8장, 가로 6장, 모두 48장의 타일을 이어 붙인 것입니다. 타일마다 노는 두 아이가 파란 물감으로 작게 그려져 있고, 네 귀퉁이에는 ‘거미’라 불리는 작은 장식이 있습니다.","죽마를 타는 아이, 그네를 밀어 주는 아이들, 땅에 쪼그려 앉아 무언가로 노는 아이 등 타일마다 다른 놀이가 그려져 있습니다. 이런 ‘아이들 놀이’ 타일은 네덜란드에서 인기가 많아 부엌이나 벽난로 둘레 벽에 붙였던 것으로 보입니다."],"spots":[["죽마","죽마를 타는 아이."],["그네","그네를 밀어 받는 아이."],["땅에서 하는 놀이","쪼그려 앉아 무언가를 늘어놓고 노는 아이."],["거미 장식","타일 네 귀퉁이의 작은 장식."],["48장의 배열","세로 8장, 가로 6장의 타일."],["오른쪽 아래 한 장","오른쪽 아래 모서리의 타일."]]},"dammolen":{"title":"다마와 뮐레의 작은 판","artist":"작자 미상","date":"1740~1760년","place":"네덜란드(암스테르담)","game":"다마(체커), 나인 멘스 모리스","medium":"호두나무, 밝은 색 메움재","size":"4.2×4.0×1.5cm","credit":"","p":["가로 4센티미터쯤 되는 호두나무 작은 판입니다. 거의 정사각형에 테두리가 서 있으며, 한쪽은 다마 판, 다른 쪽은 뮐레(나인 멘스 모리스) 판으로 쓸 수 있습니다.","다마 면은 칸을 파내고 밝은 메움재를 채워 나무 본색과 체크무늬를 이루게 했고, 뮐레 면의 선도 파서 같은 메움재로 채웠습니다. 이렇게 작으니 인형의 집을 위한 물건으로 보입니다."],"spots":[["메움 칸","파내고 밝은 메움재를 채운 칸."],["나무 칸","호두나무 바탕을 그대로 둔 칸."],["테두리","둘레에 선 테두리."],["앞 모서리","가장 앞쪽 모서리."],["두께","높이 1.5센티미터의 옆면."],["안쪽 줄","가장 안쪽 칸의 줄."]]},"karelpiece":{"title":"카롤루스 대제 초상이 있는 다마 말(한쪽 면)","artist":"작자 미상","date":"1525~1575년","place":"독일(뉘른베르크)","game":"다마(체커) 또는 백개먼류","medium":"회양목","size":"지름 5.3cm","credit":"","p":["회양목을 새긴 다마 말의 한쪽 면입니다. 가운데에 월계관에 둘러싸인 옆얼굴이 있고, 둘레에 ‘CAROLVS. MAGNVS. IMPER. AVGVST.(카롤루스 대제, 황제)’라고 새겨져 있습니다.","미술관에는 같은 방식으로 만든 말이 열 개 넘게 있으며, 티베리우스, 아그리피나, 경건왕 루트비히, 오토 대제 등 고대 로마부터 중세까지의 황제와 황후가 하나씩 새겨져 있습니다. 역대 군주를 한 벌의 말로 만든 호화로운 놀이 도구로 보입니다."],"spots":[["옆얼굴","월계관에 둘러싸인 카롤루스 대제의 옆얼굴."],["월계관","초상을 둘러싼 월계수 고리."],["CAROLVS","위쪽의 ‘CAROLVS. MAGNVS’ 글자."],["AVGVST","왼쪽의 ‘IMPER. AVGVST’ 글자."],["별","명문을 나누는 작은 별."],["테두리","말 가장자리의 단."]]},"vdberge":{"title":"네덜란드의 놀이, 즐거운 삶!(카드놀이)","artist":"피터르 판 덴 베르허(도안·간행)","date":"1694~1737년","place":"네덜란드(암스테르담)","game":"카드놀이","medium":"에칭(빨강·파랑·초록 아 라 푸페 인쇄)","size":"27.3×17.0cm","credit":"","p":["암스테르담의 판화가이자 출판업자 판 덴 베르허의 풍자화로, 제목은 ‘LE JEU HOLLANDOIS. LA BELLE VIE!’입니다. 미술관에 따르면 선술집에서 남자들이 카드를 하고, 잔을 들고 한숨짓는 남자 곁과 탁자 밑에서 악마들이 그의 돈을 따 가고 있습니다.","아래 네덜란드어 시에서 태평한 난봉꾼은 개싸움과 닭싸움, 카드와 주사위에 돈이 다 녹았다고 한탄합니다. 양옆에는 악마 둘이 독일어로 ‘주사위와 카드로 즐겁게 놀아라’ 하고 꾀는 말이 있습니다. 뒤쪽 그림에도 개싸움과 닭싸움이 그려져 있습니다."],"spots":[["잔을 든 남자","큰 가발을 쓰고 잔을 든 난봉꾼."],["손패","남자가 손에 펼친 카드."],["왼쪽 악마","남자 뒤에서 웃는 악마."],["탁자 밑의 악마","바닥에 쏟아진 동전을 긁어모으는 악마."],["개싸움 그림","벽의 그림. 개싸움과 닭싸움."],["제목과 시","‘LE JEU HOLLANDOIS’와 난봉꾼의 한탄 시."]]},"crespi":{"title":"주사위 놀이를 하는 아이들","artist":"주세페 마리아 크레스피","date":"1675~1747년","place":"이탈리아","game":"주사위","medium":"에칭","size":"22.5×15.1cm","credit":"","p":["볼로냐의 화가 크레스피가 직접 새긴 에칭입니다. 미술관에 따르면 네 아이가 길가에서 주사위 놀이를 하고, 아래에 이탈리아어 세 줄 시가 붙어 있습니다.","쪼그려 앉은 아이가 막 땅에 주사위를 굴렸고, 세 아이가 둘레에서 봅니다. 시는 뼈(주사위)와 숫자, 짧은 놀이, 줄어드는 돈을 말하고 있어, 아이들 놀이에도 노름에 대한 경계를 담은 것으로 보입니다."],"spots":[["주사위","땅에 구르는 작은 주사위."],["쪼그린 아이","막 주사위를 던진 아이."],["선 아이","들여다보듯 선 아이."],["오른쪽 아이","땅에 앉아 지켜보는 아이."],["뒤의 아이","둘 뒤에서 얼굴을 내민 아이."],["시","이탈리아어 세 줄 시."]]}};
